        public MainForm()
        {
            _saveFilePath = Path.Combine(Path.GetDirectoryName(Application.ExecutablePath) ?? ".", "morion_dm_data.dat");
            _encounters = BuildEncounters();
            _combats = BuildCombats();
            _scalings = BuildCombatScalings();
            _potions = BuildPotions();
            _ingredients = BuildIngredients();
            _injuries = BuildInjuries();
            _baseArtifacts = BuildArtifacts();
            _monsterBase64 = BuildMonsterArts();
            LoadSavedEdits();
            InitializeUi();
            ApplyFilters();
            if (_listBox.Items.Count > 0)
            {
                _listBox.SelectedIndex = 0;
            }
        }

        protected override bool ProcessCmdKey(ref Message msg, Keys keyData)
        {
            if (!(ActiveControl is TextBoxBase) && !(ActiveControl is NumericUpDown) && !(ActiveControl is ComboBox))
            {
                if (keyData == Keys.Left)
                {
                    StepSelection(-1);
                    return true;
                }
                if (keyData == Keys.Right)
                {
                    StepSelection(1);
                    return true;
                }
            }
            return base.ProcessCmdKey(ref msg, keyData);
        }

