        private Button CreateTabButton(string text, int w)
        {
            var btn = new Button
            {
                Text = text,
                Size = new Size(w, 30),
                Margin = new Padding(0, 0, 4, 0),
                FlatStyle = FlatStyle.Flat,
                BackColor = InputBg,
                ForeColor = TextMain,
                Font = new Font("Segoe UI", 8.6F, FontStyle.Bold),
                Cursor = Cursors.Hand
            };
            btn.FlatAppearance.BorderColor = BorderColor;
            btn.FlatAppearance.BorderSize = 1;
            return btn;
        }

        private void SwitchCategory(string cat)
        {
            _currentCategory = cat;
            _lastRollValue = 0;
            _lastDiceDetail = "";
            bool isArt = cat == "artifacts";
            _cmbThreat.Visible = !isArt;
            _cmbRarity.Visible = isArt;
            _btnRollArtRarity.Visible = isArt;
            _btnAddHomebrew.Visible = isArt;
            _btnRoll.Text = isArt ? "Случ. Артефакт" : "Бросить d100";
            UpdateTabHighlight();
            ApplyFilters();
            if (_listBox.Items.Count > 0)
            {
                _listBox.SelectedIndex = 0;
            }
        }

        private void SetPartyLevel(int lvl)
        {
            _partyLevel = lvl;
            UpdateLevelHighlight();
            RenderSelectedDetail();
        }

        private void StepSelection(int delta)
        {
            if (_listBox.Items.Count == 0) return;
            int idx = _listBox.SelectedIndex;
            if (idx < 0) idx = 0;
            int next = (idx + delta + _listBox.Items.Count) % _listBox.Items.Count;
            _listBox.SelectedIndex = next;
        }

        private void UpdateTabHighlight()
        {
            StyleTab(_btnRoad, _currentCategory == "road");
            StyleTab(_btnWild, _currentCategory == "wild");
            StyleTab(_btnWater, _currentCategory == "water");
            StyleTab(_btnCombat, _currentCategory == "combat");
            StyleTab(_btnPotions, _currentCategory == "potions");
            StyleTab(_btnIngredients, _currentCategory == "ingredients");
            StyleTab(_btnInjuries, _currentCategory == "injuries");
            StyleTab(_btnArtifacts, _currentCategory == "artifacts");
        }

        private void UpdateLevelHighlight()
        {
            StyleTab(_btnLvl4, _partyLevel == 4);
            StyleTab(_btnLvl6, _partyLevel == 6);
            StyleTab(_btnLvl8, _partyLevel == 8);
        }

        private void StyleTab(Button btn, bool active)
        {
            if (btn == null) return;
            btn.BackColor = active ? Color.FromArgb(48, 39, 24) : InputBg;
            btn.ForeColor = active ? Gold : TextMain;
            btn.FlatAppearance.BorderColor = active ? Gold : BorderColor;
        }

        private string Ov(string key, string fallback)
        {
            string val;
            if (_overrides.TryGetValue(key, out val)) return val;
            return fallback ?? "";
        }

        private void UpdateResetButtonState()
        {
            int count = _overrides.Count + _customArtifacts.Count;
            _btnResetEdits.Visible = count > 0;
            _btnResetEdits.Text = string.Format("Сброс ({0})", count);
        }

        private void SaveEditsToDisk()
        {
            try
            {
                var lines = new List<string>();
                foreach (var kv in _overrides)
                {
                    string k64 = Convert.ToBase64String(Encoding.UTF8.GetBytes(kv.Key));
                    string v64 = Convert.ToBase64String(Encoding.UTF8.GetBytes(kv.Value ?? ""));
                    lines.Add("OV|" + k64 + "|" + v64);
                }
                foreach (var a in _customArtifacts)
                {
                    lines.Add(string.Join("|", new string[]
                    {
                        "ART",
                        Convert.ToBase64String(Encoding.UTF8.GetBytes(a.Id ?? "")),
                        Convert.ToBase64String(Encoding.UTF8.GetBytes(a.Rarity ?? "")),
                        a.RarityRank.ToString(),
                        a.IsHomebrew ? "1" : "0",
                        Convert.ToBase64String(Encoding.UTF8.GetBytes(a.Name ?? "")),
                        Convert.ToBase64String(Encoding.UTF8.GetBytes(a.Type ?? "")),
                        Convert.ToBase64String(Encoding.UTF8.GetBytes(a.Cost ?? "")),
                        Convert.ToBase64String(Encoding.UTF8.GetBytes(a.Attunement ?? "")),
                        Convert.ToBase64String(Encoding.UTF8.GetBytes(a.Source ?? "")),
                        Convert.ToBase64String(Encoding.UTF8.GetBytes(a.Effect ?? ""))
                    }));
                }
                File.WriteAllLines(_saveFilePath, lines.ToArray(), Encoding.UTF8);
            }
            catch
            {
            }
            UpdateResetButtonState();
        }

        private void LoadSavedEdits()
        {
            _overrides.Clear();
            _customArtifacts.Clear();
            if (!File.Exists(_saveFilePath)) return;
            try
            {
                foreach (string line in File.ReadAllLines(_saveFilePath, Encoding.UTF8))
                {
                    if (string.IsNullOrWhiteSpace(line)) continue;
                    string[] parts = line.Split('|');
                    if (parts[0] == "OV" && parts.Length >= 3)
                    {
                        string k = Encoding.UTF8.GetString(Convert.FromBase64String(parts[1]));
                        string v = Encoding.UTF8.GetString(Convert.FromBase64String(parts[2]));
                        _overrides[k] = v;
                    }
                    else if (parts[0] == "ART" && parts.Length >= 11)
                    {
                        int rank = 3;
                        int.TryParse(parts[3], out rank);
                        _customArtifacts.Add(new ArtifactItem
                        {
                            Id = Encoding.UTF8.GetString(Convert.FromBase64String(parts[1])),
                            Rarity = Encoding.UTF8.GetString(Convert.FromBase64String(parts[2])),
                            RarityRank = rank,
                            IsHomebrew = parts[4] == "1",
                            Name = Encoding.UTF8.GetString(Convert.FromBase64String(parts[5])),
                            Type = Encoding.UTF8.GetString(Convert.FromBase64String(parts[6])),
                            Cost = Encoding.UTF8.GetString(Convert.FromBase64String(parts[7])),
                            Attunement = Encoding.UTF8.GetString(Convert.FromBase64String(parts[8])),
                            Source = Encoding.UTF8.GetString(Convert.FromBase64String(parts[9])),
                            Effect = Encoding.UTF8.GetString(Convert.FromBase64String(parts[10]))
                        });
                    }
                }
            }
            catch
            {
            }
        }

        private void ResetAllEdits()
        {
            if (MessageBox.Show("Сбросить все ваши правки полей и добавленные ХоумБрю-артефакты к исходным значениям?", "Сброс правок", MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
                return;
            _overrides.Clear();
            _customArtifacts.Clear();
            try { if (File.Exists(_saveFilePath)) File.Delete(_saveFilePath); } catch { }
            UpdateResetButtonState();
            ApplyFilters();
        }

        private List<ArtifactItem> GetAllArtifactsSorted()
        {
            var list = new List<ArtifactItem>();
            list.AddRange(_baseArtifacts);
            list.AddRange(_customArtifacts);
            return list.OrderBy(a => a.RarityRank).ThenBy(a => a.Name).ToList();
        }

        private void ApplyFilters()
        {
            int prevIndex = _listBox.SelectedIndex;
            string query = (_txtSearch.Text ?? "").Trim().ToLowerInvariant();
            var selectedThreat = _cmbThreat.SelectedItem as FilterOption;
            string threatCode = selectedThreat != null ? selectedThreat.Code : "all";
            var selectedRarity = _cmbRarity.SelectedItem as FilterOption;
            string rarityCode = selectedRarity != null ? selectedRarity.Code : "all";

            _listBox.BeginUpdate();
            _listBox.Items.Clear();

            if (_currentCategory == "combat")
            {
                foreach (var c in _combats)
                {
                    if (!_afterMines && c.AfterMinesOnly) continue;
                    if (threatCode != "all" && !c.Tags.Contains(threatCode)) continue;
                    string title = Ov("cmb|" + c.Id + "|title", c.Title);
                    string danger = Ov("cmb|" + c.Id + "|danger", c.DangerLevel);
                    string motiv = Ov("cmb|" + c.Id + "|motivation", c.Motivation);
                    string tactics = Ov("cmb|" + c.Id + "|tactics", c.Tactics);
                    string secret = Ov("cmb|" + c.Id + "|secret", c.TwistOrSecret);
                    if (!string.IsNullOrEmpty(query))
                    {
                        string hay = (title + " " + c.Enemies + " " + motiv + " " + tactics + " " + (_showSecrets ? secret : "")).ToLowerInvariant();
                        if (!hay.Contains(query)) continue;
                    }
                    _listBox.Items.Add(new ListRow
                    {
                        Title = title,
                        RangeLabel = string.Format("{0:00}-{1:00}", c.Min, c.Max),
                        Meta = danger,
                        IsBoss = c.IsBoss,
                        Combat = c
                    });
                }
            }
            else if (_currentCategory == "potions")
            {
                foreach (var p in _potions)
                {
                    string name = Ov("pot|" + p.Id + "|name", p.Name);
                    string src = Ov("pot|" + p.Id + "|source", p.Source);
                    string ing = Ov("pot|" + p.Id + "|ingredients", p.Ingredients);
                    string eff = Ov("pot|" + p.Id + "|effect", p.Effect);
                    string dc = Ov("pot|" + p.Id + "|dc", p.CraftDc);
                    if (!string.IsNullOrEmpty(query))
                    {
                        string hay = (name + " " + src + " " + ing + " " + eff).ToLowerInvariant();
                        if (!hay.Contains(query)) continue;
                    }
                    _listBox.Items.Add(new ListRow
                    {
                        Title = name + " (" + src + ")",
                        RangeLabel = string.Format("{0:00}-{1:00}", p.Min, p.Max),
                        Meta = "СЛ " + dc + " | " + ing,
                        IsBoss = false,
                        Potion = p
                    });
                }
            }
            else if (_currentCategory == "ingredients")
            {
                foreach (var ing in _ingredients)
                {
                    string name = Ov("ing|" + ing.Id + "|name", ing.Name);
                    string rar = Ov("ing|" + ing.Id + "|rarity", ing.Rarity);
                    string bio = Ov("ing|" + ing.Id + "|biome", ing.Biome);
                    string price = Ov("ing|" + ing.Id + "|base", ing.BasePrice);
                    if (!string.IsNullOrEmpty(query))
                    {
                        string hay = (name + " " + rar + " " + bio).ToLowerInvariant();
                        if (!hay.Contains(query)) continue;
                    }
                    _listBox.Items.Add(new ListRow
                    {
                        Title = name,
                        RangeLabel = price,
                        Meta = rar + " | " + bio,
                        IsBoss = false,
                        Ingredient = ing
                    });
                }
            }
            else if (_currentCategory == "injuries")
            {
                foreach (var inj in _injuries)
                {
                    string name = Ov("inj|" + inj.Id + "|name", inj.Name);
                    string eff = Ov("inj|" + inj.Id + "|effect", inj.Effect);
                    string rlbl = Ov("inj|" + inj.Id + "|range", inj.RangeLabel);
                    if (!string.IsNullOrEmpty(query))
                    {
                        string hay = (name + " " + eff + " " + inj.TableType).ToLowerInvariant();
                        if (!hay.Contains(query)) continue;
                    }
                    _listBox.Items.Add(new ListRow
                    {
                        Title = (inj.TableType == "heavy" ? "[4d10] " : "[2d10] ") + name,
                        RangeLabel = rlbl,
                        Meta = eff,
                        IsBoss = inj.TableType == "permanent",
                        Injury = inj
                    });
                }
            }
            else if (_currentCategory == "artifacts")
            {
                foreach (var a in GetAllArtifactsSorted())
                {
                    string rar = Ov("art|" + a.Id + "|rarity", a.Rarity);
                    string name = Ov("art|" + a.Id + "|name", a.Name);
                    string cost = Ov("art|" + a.Id + "|cost", a.Cost);
                    string eff = Ov("art|" + a.Id + "|effect", a.Effect);
                    string src = Ov("art|" + a.Id + "|source", a.Source);
                    if (rarityCode == "homebrew" && !a.IsHomebrew) continue;
                    if (rarityCode != "all" && rarityCode != "homebrew" && rar != rarityCode) continue;
                    if (!string.IsNullOrEmpty(query))
                    {
                        string hay = (name + " " + rar + " " + cost + " " + eff + " " + src).ToLowerInvariant();
                        if (!hay.Contains(query)) continue;
                    }
                    _listBox.Items.Add(new ListRow
                    {
                        Title = name,
                        RangeLabel = cost,
                        Meta = rar + " | " + src,
                        IsBoss = a.IsHomebrew,
                        Artifact = a
                    });
                }
            }
            else
            {
                foreach (var e in _encounters)
                {
                    if (e.Category != _currentCategory) continue;
                    if (!_afterMines && e.AfterMinesOnly) continue;
                    if (threatCode != "all" && !e.Tags.Contains(threatCode)) continue;
                    string title = Ov("enc|" + e.Id + "|title", e.Title);
                    string regions = Ov("enc|" + e.Id + "|regions", e.Regions);
                    string summary = Ov("enc|" + e.Id + "|summary", e.Summary);
                    string details = Ov("enc|" + e.Id + "|scene", e.SceneDetails);
                    string secret = Ov("enc|" + e.Id + "|secret", e.MasterSecret);
                    if (!string.IsNullOrEmpty(query))
                    {
                        string hay = (title + " " + regions + " " + summary + " " + details + " " + (_showSecrets ? secret : "")).ToLowerInvariant();
                        if (!hay.Contains(query)) continue;
                    }
                    _listBox.Items.Add(new ListRow
                    {
                        Title = title,
                        RangeLabel = string.Format("{0:00}-{1:00}", e.Min, e.Max),
                        Meta = regions,
                        IsBoss = e.Mood == "boss",
                        Encounter = e
                    });
                }
            }

            _listBox.EndUpdate();

            if (_listBox.Items.Count == 0)
            {
                _lblStatus.Text = "Ничего не найдено по текущему фильтру";
                _lblNavIndex.Text = "0 / 0";
                _detailBox.Clear();
                _artStrip.Visible = false;
            }
            else
            {
                int restore = (prevIndex >= 0 && prevIndex < _listBox.Items.Count) ? prevIndex : 0;
                _listBox.SelectedIndex = restore;
            }
        }

        private void DoArtifactRandomRoll(string forceRarity)
        {
            if (_currentCategory != "artifacts")
            {
                SwitchCategory("artifacts");
            }
            if (!string.IsNullOrEmpty(forceRarity))
            {
                for (int i = 0; i < _cmbRarity.Items.Count; i++)
                {
                    var opt = _cmbRarity.Items[i] as FilterOption;
                    if (opt != null && opt.Code == forceRarity)
                    {
                        _cmbRarity.SelectedIndex = i;
                        break;
                    }
                }
            }
            if (_listBox.Items.Count == 0) return;
            int idx = _rng.Next(0, _listBox.Items.Count);
            _listBox.SelectedIndex = idx;
            _lastRollValue = idx + 1;
            _lastDiceDetail = string.Format("1d{0} -> {1}", _listBox.Items.Count, idx + 1);
            RenderSelectedDetail();
        }

        private void DoInjuryRoll(string tableType)
        {
            if (_currentCategory != "injuries")
            {
                SwitchCategory("injuries");
            }
            int diceCount = tableType == "heavy" ? 4 : 2;
            int sum = 0;
            var diceList = new List<string>();
            for (int d = 0; d < diceCount; d++)
            {
                int val = _rng.Next(1, 11);
                sum += val;
                diceList.Add(val.ToString());
            }

            int matchIndex = -1;
            for (int i = 0; i < _listBox.Items.Count; i++)
            {
                var row = _listBox.Items[i] as ListRow;
                if (row == null || row.Injury == null) continue;
                if (row.Injury.TableType != tableType) continue;
                if (sum >= row.Injury.Min && (sum <= row.Injury.Max || row.Injury.Max == 40))
                {
                    matchIndex = i;
                    break;
                }
            }
            if (matchIndex >= 0)
            {
                _listBox.SelectedIndex = matchIndex;
                _lastRollValue = sum;
                _lastDiceDetail = string.Format("{0}d10 [{1}] = {2}", diceCount, string.Join("+", diceList.ToArray()), sum);
                RenderSelectedDetail();
            }
        }

        private void DoRoll(int roll)
        {
            if (_currentCategory == "artifacts")
            {
                if (_listBox.Items.Count == 0) return;
                int artIdx = (roll - 1) % _listBox.Items.Count;
                _listBox.SelectedIndex = artIdx;
                _lastRollValue = roll;
                _lastDiceDetail = string.Format("№ {0}", roll);
                RenderSelectedDetail();
                return;
            }

            if (roll < 1) roll = 1;
            if (roll > 100) roll = 100;
            if (_listBox.Items.Count == 0)
            {
                ApplyFilters();
                if (_listBox.Items.Count == 0) return;
            }

            int matchIndex = -1;
            for (int i = 0; i < _listBox.Items.Count; i++)
            {
                var row = _listBox.Items[i] as ListRow;
                if (row == null) continue;
                int min = 1, max = 100;
                if (row.Encounter != null) { min = row.Encounter.Min; max = row.Encounter.Max; }
                else if (row.Combat != null) { min = row.Combat.Min; max = row.Combat.Max; }
                else if (row.Potion != null) { min = row.Potion.Min; max = row.Potion.Max; }
                else if (row.Injury != null) { min = row.Injury.Min; max = row.Injury.Max; }
                else
                {
                    min = (i * 100 / _listBox.Items.Count) + 1;
                    max = ((i + 1) * 100 / _listBox.Items.Count);
                }

                if (roll >= min && roll <= max)
                {
                    matchIndex = i;
                    break;
                }
            }

            if (matchIndex < 0)
            {
                matchIndex = _rng.Next(0, _listBox.Items.Count);
            }

            _listBox.SelectedIndex = matchIndex;
            _lastRollValue = roll;
            _lastDiceDetail = "";
            RenderSelectedDetail();

            var picked = _listBox.Items[matchIndex] as ListRow;
            if (picked != null)
            {
                string logEntry = string.Format("[{0}] d100 -> {1}: {2}", _currentCategory.ToUpperInvariant(), roll, picked.Title);
                _historyLog.Insert(0, logEntry);
                _historyRolls.Insert(0, roll);
                _historyCats.Insert(0, _currentCategory);
                if (_historyLog.Count > 12)
                {
                    _historyLog.RemoveAt(_historyLog.Count - 1);
                    _historyRolls.RemoveAt(_historyRolls.Count - 1);
                    _historyCats.RemoveAt(_historyCats.Count - 1);
                }
                _suppressHistoryEvent = true;
                _cmbHistory.Items.Clear();
                foreach (var item in _historyLog) _cmbHistory.Items.Add(item);
                _cmbHistory.SelectedIndex = 0;
                _cmbHistory.ForeColor = TextMain;
                _suppressHistoryEvent = false;
            }
        }

        private Image GetCachedImage(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            if (_imageCache.ContainsKey(key)) return _imageCache[key];
            string b64;
            if (!_monsterBase64.TryGetValue(key, out b64)) return null;
            try
            {
                byte[] bytes = Convert.FromBase64String(b64);
                using (var ms = new MemoryStream(bytes))
                {
                    var img = Image.FromStream(ms);
                    _imageCache[key] = img;
                    return img;
                }
            }
            catch
            {
                return null;
            }
        }

        private void ShowZoomArt(Image img, string caption)
        {
            if (img == null) return;
            var modal = new Form
            {
                Text = caption,
                Size = new Size(640, 680),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = BgDark,
                ForeColor = Gold
            };
            var pic = new PictureBox
            {
                Dock = DockStyle.Fill,
                Image = img,
                SizeMode = PictureBoxSizeMode.Zoom,
                BackColor = BgDark
            };
            var lbl = new Label
            {
                Dock = DockStyle.Bottom,
                Height = 36,
                Text = caption + "  (Закрыть: Esc или клик)",
                ForeColor = Gold,
                Font = new Font("Segoe UI", 10F, FontStyle.Bold),
                TextAlign = ContentAlignment.MiddleCenter
            };
            pic.Click += delegate { modal.Close(); };
            modal.KeyPreview = true;
            modal.KeyDown += delegate(object s, KeyEventArgs ke) { if (ke.KeyCode == Keys.Escape) modal.Close(); };
            modal.Controls.Add(pic);
            modal.Controls.Add(lbl);
            modal.ShowDialog(this);
        }

        private void UpdateArtStripForCombat(string combatId)
        {
            _artStrip.Controls.Clear();
            if (string.IsNullOrEmpty(combatId))
            {
                _artStrip.Visible = false;
                return;
            }
            var scaling = _scalings.FirstOrDefault(s => s.CombatId == combatId && s.PartyLevel == _partyLevel);
            if (scaling == null || scaling.StatBlocks == null || scaling.StatBlocks.Count == 0)
            {
                _artStrip.Visible = false;
                return;
            }
            bool addedAny = false;
            for (int idx = 0; idx < scaling.StatBlocks.Count; idx++)
            {
                var sb = scaling.StatBlocks[idx];
                string sbPrefix = "sb|" + combatId + "|" + _partyLevel + "|" + idx + "|";
                string sbName = Ov(sbPrefix + "name", sb.Name);
                string sbCount = Ov(sbPrefix + "count", sb.Count);
                var img = GetCachedImage(sb.ImageKey);
                if (img == null) continue;
                addedAny = true;
                var card = new Panel
                {
                    Width = 128,
                    Height = 118,
                    Margin = new Padding(0, 0, 10, 0),
                    BackColor = PanelBg,
                    Cursor = Cursors.Hand
                };
                var pic = new PictureBox
                {
                    Dock = DockStyle.Top,
                    Height = 94,
                    Image = img,
                    SizeMode = PictureBoxSizeMode.Zoom,
                    BackColor = Color.FromArgb(244, 240, 232),
                    Cursor = Cursors.Hand
                };
                var cap = new Label
                {
                    Dock = DockStyle.Fill,
                    Text = sbCount + " " + sbName,
                    ForeColor = Gold,
                    Font = new Font("Segoe UI", 7.5F, FontStyle.Bold),
                    TextAlign = ContentAlignment.MiddleCenter
                };
                var zoomData = new object[] { img, sbCount + " " + sbName };
                pic.Tag = zoomData;
                cap.Tag = zoomData;
                pic.Click += ArtThumb_Click;
                cap.Click += ArtThumb_Click;
                card.Controls.Add(cap);
                card.Controls.Add(pic);
                _artStrip.Controls.Add(card);
            }
            _artStrip.Visible = addedAny;
        }

        private void ArtThumb_Click(object sender, EventArgs e)
        {
            var ctrl = sender as Control;
            if (ctrl == null) return;
            var pair = ctrl.Tag as object[];
            if (pair == null || pair.Length < 2) return;
            ShowZoomArt(pair[0] as Image, pair[1] as string);
        }

        private void ListBox_DrawItem(object sender, DrawItemEventArgs e)
        {
            if (e.Index < 0 || e.Index >= _listBox.Items.Count) return;
            var row = _listBox.Items[e.Index] as ListRow;
            if (row == null) return;

            bool selected = (e.State & DrawItemState.Selected) == DrawItemState.Selected;
            Color bg = selected ? Color.FromArgb(34, 38, 48) : (e.Index % 2 == 0 ? BgDark : Color.FromArgb(14, 17, 22));
            using (var br = new SolidBrush(bg))
            {
                e.Graphics.FillRectangle(br, e.Bounds);
            }
            using (var pen = new Pen(Color.FromArgb(26, 30, 38)))
            {
                e.Graphics.DrawLine(pen, e.Bounds.Left, e.Bounds.Bottom - 1, e.Bounds.Right, e.Bounds.Bottom - 1);
            }

            var badgeRect = new Rectangle(e.Bounds.Left + 10, e.Bounds.Top + 12, 74, 28);
            using (var bBr = new SolidBrush(selected ? Color.FromArgb(48, 39, 24) : InputBg))
            using (var bPen = new Pen(selected ? Gold : BorderColor))
            {
                e.Graphics.FillRectangle(bBr, badgeRect);
                e.Graphics.DrawRectangle(bPen, badgeRect);
            }
            using (var fMono = new Font("Consolas", 8F, FontStyle.Bold))
            {
                TextRenderer.DrawText(e.Graphics, row.RangeLabel, fMono, badgeRect, row.IsBoss ? DangerRed : Gold, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis);
            }

            var titleRect = new Rectangle(e.Bounds.Left + 94, e.Bounds.Top + 7, e.Bounds.Width - 102, 22);
            var metaRect = new Rectangle(e.Bounds.Left + 94, e.Bounds.Top + 29, e.Bounds.Width - 102, 18);

            Color titleColor = row.IsBoss ? DangerRed : (selected ? Gold : TextMain);
            using (var fTitle = new Font("Segoe UI", 9.4F, FontStyle.Bold))
            using (var fMeta = new Font("Segoe UI", 8F, FontStyle.Regular))
            {
                TextRenderer.DrawText(e.Graphics, row.Title, fTitle, titleRect, titleColor, TextFormatFlags.EndEllipsis | TextFormatFlags.SingleLine);
                TextRenderer.DrawText(e.Graphics, row.Meta, fMeta, metaRect, TextMuted, TextFormatFlags.EndEllipsis | TextFormatFlags.SingleLine);
            }
        }

        private void RenderSelectedDetail()
        {
            var row = _listBox.SelectedItem as ListRow;
            if (row == null) return;

            _detailBox.Clear();
            int idx = _listBox.SelectedIndex + 1;
            int total = _listBox.Items.Count;
            _lblNavIndex.Text = string.Format("{0} / {1}", idx, total);

            if (row.Encounter != null)
            {
                var e = row.Encounter;
                string title = Ov("enc|" + e.Id + "|title", e.Title);
                string regions = Ov("enc|" + e.Id + "|regions", e.Regions);
                string summary = Ov("enc|" + e.Id + "|summary", e.Summary);
                string scene = Ov("enc|" + e.Id + "|scene", e.SceneDetails);
                string choices = Ov("enc|" + e.Id + "|choices", e.ChoicesOrChecks);
                string reward = Ov("enc|" + e.Id + "|reward", e.RewardOrConsequence);
                string secret = Ov("enc|" + e.Id + "|secret", e.MasterSecret);

                _lblStatus.Text = _lastRollValue > 0
                    ? string.Format("БРОСОК d100 -> {0} (диапазон {1}-{2})  |  Партия: 4 игрока · {3} ур.", _lastRollValue, e.Min, e.Max, _partyLevel)
                    : string.Format("ТАБЛИЦА: {0}  |  d100: {1}-{2}  |  Партия: 4 игрока · {3} ур.", _currentCategory.ToUpperInvariant(), e.Min, e.Max, _partyLevel);

                UpdateArtStripForCombat(e.LinkedCombatId);

                AppendStyled(title + "\n", 15F, FontStyle.Bold, e.Mood == "boss" ? DangerRed : Gold);
                AppendStyled("Локации: " + regions + (e.AfterMinesOnly ? "  |  Этап: После шахт" : "") + "\n\n", 9.5F, FontStyle.Italic, TextMuted);

                AppendSection("Кратко: ", summary);
                AppendSection("Сцена: ", scene);
                AppendSection("Проверки и выбор: ", choices);
                AppendSection("Награда / исход: ", reward);

                if (_showSecrets && !string.IsNullOrEmpty(secret))
                {
                    AppendStyled("\n[СЕКРЕТ МАСТЕРА]\n", 9.5F, FontStyle.Bold, SecretPurple);
                    AppendStyled(secret + "\n", 10F, FontStyle.Regular, SecretPurple);
                }

                if (!string.IsNullOrEmpty(e.LinkedCombatId))
                {
                    var cmb = _combats.FirstOrDefault(c => c.Id == e.LinkedCombatId);
                    if (cmb != null)
                    {
                        AppendStyled("\n----------------------------------------------------------------------\n", 9F, FontStyle.Regular, BorderColor);
                        AppendCombatBlock(cmb);
                    }
                }
            }
            else if (row.Combat != null)
            {
                var c = row.Combat;
                _lblStatus.Text = _lastRollValue > 0
                    ? string.Format("БРОСОК БОЯ d100 -> {0} (диапазон {1}-{2})  |  4 игрока · {3} ур.", _lastRollValue, c.Min, c.Max, _partyLevel)
                    : string.Format("БОЕВОЙ ЭНКАУНТЕР  |  d100: {0}-{1}  |  4 игрока · {2} ур.", c.Min, c.Max, _partyLevel);
                UpdateArtStripForCombat(c.Id);
                AppendCombatBlock(c);
            }
            else if (row.Potion != null)
            {
                _artStrip.Visible = false;
                var p = row.Potion;
                string name = Ov("pot|" + p.Id + "|name", p.Name);
                string src = Ov("pot|" + p.Id + "|source", p.Source);
                string dc = Ov("pot|" + p.Id + "|dc", p.CraftDc);
                string time = Ov("pot|" + p.Id + "|time", p.CraftTime);
                string eff = Ov("pot|" + p.Id + "|effect", p.Effect);
                string ing = Ov("pot|" + p.Id + "|ingredients", p.Ingredients);
                string app = Ov("pot|" + p.Id + "|appearance", p.Appearance);

                _lblStatus.Text = _lastRollValue > 0
                    ? string.Format("ЛУТ ЗЕЛЬЯ d100 -> {0} (диапазон {1}-{2})", _lastRollValue, p.Min, p.Max)
                    : string.Format("ТАБЛИЦА ЗЕЛИЙ  |  d100: {0}-{1}", p.Min, p.Max);
                AppendStyled(name + " (" + src + ")\n", 15F, FontStyle.Bold, Gold);
                AppendStyled(string.Format("d100: {0}-{1}  |  СЛ варки: {2}  |  Время: {3}\n\n", p.Min, p.Max, dc, time), 9.5F, FontStyle.Italic, TextMuted);
                AppendSection("Эффект: ", eff);
                AppendSection("Ингредиенты: ", ing);
                AppendSection("Внешний вид / запах / консистенция: ", app);
            }
            else if (row.Ingredient != null)
            {
                _artStrip.Visible = false;
                var ing = row.Ingredient;
                string name = Ov("ing|" + ing.Id + "|name", ing.Name);
                string rar = Ov("ing|" + ing.Id + "|rarity", ing.Rarity);
                string bio = Ov("ing|" + ing.Id + "|biome", ing.Biome);
                _lblStatus.Text = string.Format("АЛХИМИЧЕСКИЙ ИНГРЕДИЕНТ  |  {0}", rar);
                AppendStyled(name + "\n", 15F, FontStyle.Bold, Gold);
                AppendStyled("Редкость: " + rar + "  |  Родной биом: " + bio + "\n\n", 9.5F, FontStyle.Italic, TextMuted);
                AppendSection("Базовая цена: ", Ov("ing|" + ing.Id + "|base", ing.BasePrice));
                AppendSection("Северное предгорье: ", Ov("ing|" + ing.Id + "|north", ing.NorthFoothills));
                AppendSection("Тундра: ", Ov("ing|" + ing.Id + "|tundra", ing.Tundra));
                AppendSection("Пустыня: ", Ov("ing|" + ing.Id + "|desert", ing.Desert));
                AppendSection("Оазис: ", Ov("ing|" + ing.Id + "|oasis", ing.Oasis));
                AppendSection("Умеренные широты: ", Ov("ing|" + ing.Id + "|temp", ing.Temperate));
                AppendSection("Влажный юг: ", Ov("ing|" + ing.Id + "|south", ing.HumidSouth));
                AppendSection("Столица: ", Ov("ing|" + ing.Id + "|cap", ing.Capital));
            }
            else if (row.Injury != null)
            {
                _artStrip.Visible = false;
                var inj = row.Injury;
                string name = Ov("inj|" + inj.Id + "|name", inj.Name);
                string rlbl = Ov("inj|" + inj.Id + "|range", inj.RangeLabel);
                string eff = Ov("inj|" + inj.Id + "|effect", inj.Effect);
                string tblTitle = inj.TableType == "heavy" ? "ТЯЖЁЛАЯ ТРАВМА (4d10)" : "ПОСТОЯННАЯ ТРАВМА (2d10)";
                _lblStatus.Text = !string.IsNullOrEmpty(_lastDiceDetail)
                    ? string.Format("{0}  |  Бросок: {1}  |  Строка {2}", tblTitle, _lastDiceDetail, rlbl)
                    : string.Format("{0}  |  Значение кубиков: {1}", tblTitle, rlbl);
                AppendStyled(name + "\n", 15F, FontStyle.Bold, inj.TableType == "permanent" ? DangerRed : Gold);
                AppendStyled(string.Format("{0}  |  Диапазон: {1}\n\n", tblTitle, rlbl), 9.5F, FontStyle.Italic, TextMuted);
                AppendSection("Эффект травмы: ", eff);
            }
            else if (row.Artifact != null)
            {
                _artStrip.Visible = false;
                var a = row.Artifact;
                string rar = Ov("art|" + a.Id + "|rarity", a.Rarity);
                string name = Ov("art|" + a.Id + "|name", a.Name);
                string type = Ov("art|" + a.Id + "|type", a.Type);
                string cost = Ov("art|" + a.Id + "|cost", a.Cost);
                string att = Ov("art|" + a.Id + "|attunement", a.Attunement);
                string src = Ov("art|" + a.Id + "|source", a.Source);
                string eff = Ov("art|" + a.Id + "|effect", a.Effect);

                _lblStatus.Text = !string.IsNullOrEmpty(_lastDiceDetail)
                    ? string.Format("АРТЕФАКТЫ (по редкости)  |  Случайный выбор: {0}  |  Цена: {1}", _lastDiceDetail, cost)
                    : string.Format("АРТЕФАКТ: {0}  |  Стоимость: {1}", rar.ToUpperInvariant(), cost);

                AppendStyled(name + (a.IsHomebrew ? "  [ХОУМБРЮ]" : "") + "\n", 15F, FontStyle.Bold, a.IsHomebrew ? EmeraldOk : Gold);
                AppendStyled(string.Format("Редкость: {0}   |   Стоимость: {1}   |   Настройка: {2}\n\n", rar, cost, att), 10F, FontStyle.Bold, Gold);
                AppendSection("Тип предмета: ", type);
                AppendSection("Источник / Босс: ", src);
                AppendSection("Свойства и механика: ", eff);

                AppendStyled("\n----------------------------------------------------------------------\n", 9F, FontStyle.Regular, BorderColor);
                AppendStyled("[СВОДНАЯ ТАБЛИЦА ТЕКУЩЕГО ФИЛЬТРА ПО РЕДКОСТИ И СТОИМОСТИ]\n", 9.5F, FontStyle.Bold, StatCyan);
                for (int i = 0; i < _listBox.Items.Count; i++)
                {
                    var lr = _listBox.Items[i] as ListRow;
                    if (lr == null || lr.Artifact == null) continue;
                    var itemA = lr.Artifact;
                    string iRar = Ov("art|" + itemA.Id + "|rarity", itemA.Rarity);
                    string iName = Ov("art|" + itemA.Id + "|name", itemA.Name);
                    string iCost = Ov("art|" + itemA.Id + "|cost", itemA.Cost);
                    string mark = itemA.Id == a.Id ? ">> " : "   ";
                    AppendStyled(string.Format("{0}[{1}] {2}  —  {3}\n", mark, iRar, iName, iCost), 9F, itemA.Id == a.Id ? FontStyle.Bold : FontStyle.Regular, itemA.Id == a.Id ? Gold : TextMuted);
                }
            }

            _detailBox.SelectionStart = 0;
            _detailBox.ScrollToCaret();
        }

        private void AppendCombatBlock(CombatItem c)
        {
            string title = Ov("cmb|" + c.Id + "|title", c.Title);
            string danger = Ov("cmb|" + c.Id + "|danger", c.DangerLevel);
            string motiv = Ov("cmb|" + c.Id + "|motivation", c.Motivation);
            string tactics = Ov("cmb|" + c.Id + "|tactics", c.Tactics);
            string reward = Ov("cmb|" + c.Id + "|reward", c.Reward);
            string secret = Ov("cmb|" + c.Id + "|secret", c.TwistOrSecret);

            AppendStyled(title + "\n", 14F, FontStyle.Bold, c.IsBoss ? DangerRed : Gold);
            AppendStyled("Угроза: " + danger + (c.AfterMinesOnly ? "  |  Только после шахт" : "") + "\n\n", 9.5F, FontStyle.Bold, c.IsBoss ? DangerRed : TextMuted);

            var scaling = _scalings.FirstOrDefault(s => s.CombatId == c.Id && s.PartyLevel == _partyLevel);
            if (scaling != null)
            {
                string comp = Ov("tier|" + c.Id + "|" + _partyLevel + "|comp", scaling.Composition);
                string note = Ov("tier|" + c.Id + "|" + _partyLevel + "|note", scaling.ScalingNote);
                AppendStyled(string.Format("[СКЕЙЛИНГ ПОД ПАРТИЮ: {0}]\n", scaling.DifficultyLabel), 10F, FontStyle.Bold, StatCyan);
                AppendStyled("Состав врагов: " + comp + "\n", 10F, FontStyle.Bold, TextMain);
                AppendStyled(note + "\n\n", 9.5F, FontStyle.Italic, TextMuted);
            }
            else
            {
                AppendSection("Состав врагов: ", c.Enemies);
            }

            AppendSection("Повод / Мотивация: ", motiv);
            AppendSection("Тактика поля боя: ", tactics);
            AppendSection("Награда / Зелья / ХоумБрю: ", reward);

            if (scaling != null && scaling.StatBlocks != null && scaling.StatBlocks.Count > 0)
            {
                AppendStyled("\n[ПОЛНЫЕ СТАТБЛОКИ ВРАГОВ (dnd.su)]\n\n", 10.5F, FontStyle.Bold, StatCyan);
                for (int idx = 0; idx < scaling.StatBlocks.Count; idx++)
                {
                    var sb = scaling.StatBlocks[idx];
                    string p = "sb|" + c.Id + "|" + _partyLevel + "|" + idx + "|";
                    string name = Ov(p + "name", sb.Name);
                    string count = Ov(p + "count", sb.Count);
                    string typeSize = Ov(p + "typesize", sb.TypeSize);
                    string cr = Ov(p + "cr", sb.Cr);
                    string ac = Ov(p + "ac", sb.Ac);
                    string hp = Ov(p + "hp", sb.Hp);
                    string speed = Ov(p + "speed", sb.Speed);
                    string str = Ov(p + "str", sb.Str);
                    string dex = Ov(p + "dex", sb.Dex);
                    string con = Ov(p + "con", sb.Con);
                    string intel = Ov(p + "int", sb.Int);
                    string wis = Ov(p + "wis", sb.Wis);
                    string cha = Ov(p + "cha", sb.Cha);
                    string saves = Ov(p + "saves", sb.SavingThrows);
                    string esaves = Ov(p + "esaves", sb.EnemySavesDC);
                    string skills = Ov(p + "skills", sb.Skills);
                    string def = Ov(p + "def", sb.Defenses);
                    string senses = Ov(p + "senses", sb.SensesLangs);
                    string attacks = Ov(p + "attacks", sb.Attacks);
                    string traits = Ov(p + "traits", sb.Traits);

                    AppendStyled(string.Format("• {0} ({1})  [{2}]\n", name, count, typeSize), 11F, FontStyle.Bold, Gold);
                    AppendStyled(string.Format("  CR: {0}   |   КД: {1}   |   Хиты: {2}   |   Скорость: {3}\n", cr, ac, hp, speed), 9.6F, FontStyle.Bold, TextMain);
                    AppendStyled(string.Format("  СИЛ {0}   ЛОВ {1}   ТЕЛ {2}   ИНТ {3}   МУД {4}   ХАР {5}\n", str, dex, con, intel, wis, cha), 9.4F, FontStyle.Bold, StatCyan);
                    AppendStyled("  Спасброски монстра: " + saves + "\n", 9.4F, FontStyle.Regular, EmeraldOk);
                    AppendStyled("  СПАСБРОСКИ ПРОТИВ ВРАГА (СЛ игрокам): " + esaves + "\n", 9.6F, FontStyle.Bold, DangerRed);
                    AppendStyled("  Навыки: " + skills + "\n", 9.2F, FontStyle.Regular, TextMain);
                    AppendStyled("  Сопротивления / Иммунитеты: " + def + "\n", 9.2F, FontStyle.Regular, TextMain);
                    AppendStyled("  Чувства и языки: " + senses + "\n", 9.2F, FontStyle.Italic, TextMuted);
                    AppendStyled("  Атаки и действия: " + attacks + "\n", 9.6F, FontStyle.Regular, TextMain);
                    AppendStyled("  Особенности / Реакции / Легендарки: " + traits + "\n\n", 9.2F, FontStyle.Italic, TextMuted);
                }
            }

            if (_showSecrets && !string.IsNullOrEmpty(secret))
            {
                AppendStyled("[СЕКРЕТ / ТВИСТ МАСТЕРА]\n", 9.5F, FontStyle.Bold, SecretPurple);
                AppendStyled(secret + "\n", 10F, FontStyle.Regular, SecretPurple);
            }
        }

        private void AppendSection(string label, string body)
        {
            AppendStyled(label, 10F, FontStyle.Bold, Gold);
            AppendStyled((body ?? "") + "\n\n", 10F, FontStyle.Regular, TextMain);
        }

        private void AppendStyled(string text, float size, FontStyle style, Color color)
        {
            _detailBox.SelectionStart = _detailBox.TextLength;
            _detailBox.SelectionLength = 0;
            using (var f = new Font("Segoe UI", size, style))
            {
                _detailBox.SelectionFont = f;
                _detailBox.SelectionColor = color;
                _detailBox.AppendText(text);
            }
        }

        private void OpenEditDialogForCurrent()
        {
            var row = _listBox.SelectedItem as ListRow;
            if (row == null) return;
            var specs = new List<EditableFieldSpec>();

            if (row.Encounter != null)
            {
                var e = row.Encounter;
                specs.Add(MakeSpec("enc|" + e.Id + "|title", "Название сцены", e.Title, false));
                specs.Add(MakeSpec("enc|" + e.Id + "|regions", "Локации", e.Regions, false));
                specs.Add(MakeSpec("enc|" + e.Id + "|summary", "Кратко", e.Summary, true));
                specs.Add(MakeSpec("enc|" + e.Id + "|scene", "Сцена", e.SceneDetails, true));
                specs.Add(MakeSpec("enc|" + e.Id + "|choices", "Проверки и выбор", e.ChoicesOrChecks, true));
                specs.Add(MakeSpec("enc|" + e.Id + "|reward", "Награда / исход", e.RewardOrConsequence, true));
                specs.Add(MakeSpec("enc|" + e.Id + "|secret", "Секрет Мастера", e.MasterSecret, true));
            }
            else if (row.Combat != null)
            {
                var c = row.Combat;
                specs.Add(MakeSpec("cmb|" + c.Id + "|title", "Название боя", c.Title, false));
