            else if (row.Ingredient != null)
            {
                var ing = row.Ingredient;
                specs.Add(MakeSpec("ing|" + ing.Id + "|name", "Название", ing.Name, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|rarity", "Редкость", ing.Rarity, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|biome", "Родной биом", ing.Biome, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|base", "Базовая цена", ing.BasePrice, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|north", "Северное предгорье", ing.NorthFoothills, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|tundra", "Тундра", ing.Tundra, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|desert", "Пустыня", ing.Desert, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|oasis", "Оазис", ing.Oasis, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|temp", "Умеренные широты", ing.Temperate, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|south", "Влажный юг", ing.HumidSouth, false));
                specs.Add(MakeSpec("ing|" + ing.Id + "|cap", "Столица", ing.Capital, false));
            }
            else if (row.Injury != null)
            {
                var inj = row.Injury;
                specs.Add(MakeSpec("inj|" + inj.Id + "|range", "Диапазон броска", inj.RangeLabel, false));
                specs.Add(MakeSpec("inj|" + inj.Id + "|name", "Название травмы", inj.Name, false));
                specs.Add(MakeSpec("inj|" + inj.Id + "|effect", "Эффект травмы", inj.Effect, true));
            }
            else if (row.Artifact != null)
            {
                var a = row.Artifact;
                specs.Add(MakeSpec("art|" + a.Id + "|name", "Название артефакта", a.Name, false));
                specs.Add(MakeSpec("art|" + a.Id + "|rarity", "Редкость", a.Rarity, false));
                specs.Add(MakeSpec("art|" + a.Id + "|cost", "Стоимость", a.Cost, false));
                specs.Add(MakeSpec("art|" + a.Id + "|type", "Тип предмета", a.Type, false));
                specs.Add(MakeSpec("art|" + a.Id + "|attunement", "Настройка", a.Attunement, false));
                specs.Add(MakeSpec("art|" + a.Id + "|source", "Источник / Босс", a.Source, false));
                specs.Add(MakeSpec("art|" + a.Id + "|effect", "Эффект и механика", a.Effect, true));
            }

            if (specs.Count == 0) return;

            var dlg = new Form
            {
                Text = "Редактирование всех полей записи",
                Size = new Size(860, 680),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = BgDark,
                ForeColor = TextMain,
                Font = new Font("Segoe UI", 9.5F)
            };

            var scroll = new Panel
            {
                Dock = DockStyle.Fill,
                AutoScroll = true,
                Padding = new Padding(16)
            };

            var inputs = new Dictionary<string, TextBox>();
            int y = 8;
            foreach (var sp in specs)
            {
                var lbl = new Label
                {
                    Text = sp.Label,
                    Location = new Point(12, y),
                    Size = new Size(780, 18),
                    ForeColor = Gold,
                    Font = new Font("Segoe UI", 8.8F, FontStyle.Bold)
                };
                scroll.Controls.Add(lbl);
                y += 20;

                int boxH = sp.Multiline ? 58 : 26;
                var tb = new TextBox
                {
                    Text = sp.CurrentValue,
                    Location = new Point(12, y),
                    Size = new Size(790, boxH),
                    Multiline = sp.Multiline,
                    ScrollBars = sp.Multiline ? ScrollBars.Vertical : ScrollBars.None,
                    BackColor = InputBg,
                    ForeColor = TextMain,
                    BorderStyle = BorderStyle.FixedSingle
                };
                scroll.Controls.Add(tb);
                inputs[sp.Key] = tb;
                y += boxH + 10;
            }

            var footer = new Panel
            {
                Dock = DockStyle.Bottom,
                Height = 52,
                BackColor = PanelBg,
                Padding = new Padding(16, 10, 16, 10)
            };

            var btnSave = new Button
            {
                Text = "Сохранить все изменения",
                Size = new Size(190, 32),
                Dock = DockStyle.Right,
                FlatStyle = FlatStyle.Flat,
                BackColor = Gold,
                ForeColor = Color.FromArgb(17, 19, 23),
                Font = new Font("Segoe UI", 9.2F, FontStyle.Bold)
            };
            btnSave.FlatAppearance.BorderSize = 0;

            var btnCancel = CreateTabButton("Отмена", 100);
            btnCancel.Dock = DockStyle.Left;
            btnCancel.Click += delegate { dlg.Close(); };

            btnSave.Click += delegate
            {
                foreach (var sp in specs)
                {
                    string newVal = inputs[sp.Key].Text;
                    if (newVal == (sp.DefaultValue ?? ""))
                    {
                        _overrides.Remove(sp.Key);
                    }
                    else
                    {
                        _overrides[sp.Key] = newVal;
                    }
                }
                SaveEditsToDisk();
                ApplyFilters();
                dlg.Close();
            };

            footer.Controls.Add(btnCancel);
            footer.Controls.Add(btnSave);
            dlg.Controls.Add(scroll);
            dlg.Controls.Add(footer);
            dlg.ShowDialog(this);
        }

        private EditableFieldSpec MakeSpec(string key, string label, string defVal, bool multi)
        {
            return new EditableFieldSpec
            {
                Key = key,
                Label = label,
                DefaultValue = defVal ?? "",
                CurrentValue = Ov(key, defVal ?? ""),
                Multiline = multi
            };
        }

        private void OpenAddHomebrewDialog()
        {
            var dlg = new Form
            {
                Text = "Добавить новый ХоумБрю-артефакт",
                Size = new Size(560, 480),
                StartPosition = FormStartPosition.CenterParent,
                BackColor = BgDark,
                ForeColor = TextMain
            };

            var lblName = new Label { Text = "Название:", Location = new Point(16, 14), AutoSize = true, ForeColor = Gold };
            var txtName = new TextBox { Location = new Point(16, 34), Width = 508, BackColor = InputBg, ForeColor = TextMain };

            var lblRar = new Label { Text = "Редкость:", Location = new Point(16, 68), AutoSize = true, ForeColor = Gold };
            var cmbRar = new ComboBox { Location = new Point(16, 88), Width = 240, DropDownStyle = ComboBoxStyle.DropDownList, BackColor = InputBg, ForeColor = TextMain };
            cmbRar.Items.AddRange(new object[] { "Обычный", "Необычный", "Редкий", "Очень редкий", "Легендарный" });
            cmbRar.SelectedIndex = 2;

            var lblCost = new Label { Text = "Стоимость:", Location = new Point(276, 68), AutoSize = true, ForeColor = Gold };
            var txtCost = new TextBox { Text = "3 500 зм", Location = new Point(276, 88), Width = 248, BackColor = InputBg, ForeColor = TextMain };

            var lblType = new Label { Text = "Тип и настройка:", Location = new Point(16, 122), AutoSize = true, ForeColor = Gold };
            var txtType = new TextBox { Text = "Чудесный предмет", Location = new Point(16, 142), Width = 240, BackColor = InputBg, ForeColor = TextMain };
            var txtAtt = new TextBox { Text = "Требуется", Location = new Point(276, 142), Width = 248, BackColor = InputBg, ForeColor = TextMain };

            var lblSrc = new Label { Text = "Источник / Босс:", Location = new Point(16, 176), AutoSize = true, ForeColor = Gold };
            var txtSrc = new TextBox { Text = "ХоумБрю Мастера", Location = new Point(16, 196), Width = 508, BackColor = InputBg, ForeColor = TextMain };

            var lblEff = new Label { Text = "Эффект и механика:", Location = new Point(16, 230), AutoSize = true, ForeColor = Gold };
            var txtEff = new TextBox { Location = new Point(16, 250), Size = new Size(508, 120), Multiline = true, BackColor = InputBg, ForeColor = TextMain };

            var btnSave = new Button
            {
                Text = "Добавить артефакт",
                Location = new Point(344, 386),
                Size = new Size(180, 32),
                FlatStyle = FlatStyle.Flat,
                BackColor = EmeraldOk,
                ForeColor = Color.FromArgb(17, 19, 23),
                Font = new Font("Segoe UI", 9.2F, FontStyle.Bold)
            };
            btnSave.FlatAppearance.BorderSize = 0;
            btnSave.Click += delegate
            {
                if (string.IsNullOrWhiteSpace(txtName.Text)) return;
                string rar = cmbRar.SelectedItem.ToString();
                int rank = cmbRar.SelectedIndex + 1;
                _customArtifacts.Add(new ArtifactItem
                {
                    Id = "art-hb-" + DateTime.Now.Ticks.ToString(),
                    Rarity = rar,
                    RarityRank = rank,
                    IsHomebrew = true,
                    Name = txtName.Text.Trim(),
                    Type = txtType.Text.Trim(),
                    Cost = txtCost.Text.Trim(),
                    Attunement = txtAtt.Text.Trim(),
                    Source = txtSrc.Text.Trim(),
                    Effect = txtEff.Text.Trim()
                });
                SaveEditsToDisk();
                SwitchCategory("artifacts");
                dlg.Close();
            };

            dlg.Controls.AddRange(new Control[] { lblName, txtName, lblRar, cmbRar, lblCost, txtCost, lblType, txtType, txtAtt, lblSrc, txtSrc, lblEff, txtEff, btnSave });
            dlg.ShowDialog(this);
        }

        private void CopyCurrentDetail()
        {
            if (string.IsNullOrWhiteSpace(_detailBox.Text)) return;
            try
            {
                Clipboard.SetText(_lblStatus.Text + "\r\n" + _detailBox.Text.Replace("\n", "\r\n"));
                _btnCopy.Text = "Скопировано!";
                var t = new Timer { Interval = 1500 };
                t.Tick += delegate
                {
                    _btnCopy.Text = "Копировать";
                    t.Stop();
                    t.Dispose();
                };
                t.Start();
            }
            catch
            {
            }
        }

