                new EncounterItem { Id = "road-04", Category = "road", Min = 13, Max = 16, Title = "Мёртвая тишина и вороньё на виселице", Mood = "omen", Regions = "Тракт к Корну · Дорога у Тихого Лога · Окрестности Болота", Tags = new string[] { "darklands", "illithids" }, AfterMinesOnly = false, Summary = "Сотня ворон сидит на ветвях вдоль дороги в абсолютном безмолвии.", SceneDetails = "Ни единого карканья — птицы синхронно поворачивают головы вслед за путниками. Под деревом — следы когтей и лужица вязкой фиолетово-чёрной слизи, от которой болит переносица.", ChoicesOrChecks = "Природа/Магия Сл 14 — определить, что это не некротическая гниль Тёмных Земель, а остатки псионического фона. Животноводство/Выживание Сл 12 — птицы явно под чьим-то наблюдением.", MasterSecret = "Через ворон местность прощупывает разум Иллитида из подземных шахт или их разведчик.", RewardOrConsequence = "Если герои быстро уходят и не трогают слизь — избегают засады; если копаются в ней — на следующую ночь снится «око из-под земли» (помеха на первый спасбросок Мудрости).", LinkedCombatId = "" },
                new EncounterItem { Id = "road-05", Category = "road", Min = 17, Max = 20, Title = "Боевой энкаунтер: Дезертиры из-под Востоколя", Mood = "combat", Regions = "Восточные и центральные тракты", Tags = new string[] { "empire" }, AfterMinesOnly = false, Summary = "Из-за поворота вылетают арбалетные болты: отбившиеся солдаты готовы убивать ради коней и еды.", SceneDetails = "Голодные пехотинцы в грязных плащах Тирров затаились за придорожным валуном. Они в панике и уверены, что их пришли вешать за бегство.", ChoicesOrChecks = "Убеждение Сл 15 до первого удара позволяет остановить бойню и разговорить командира. Переход в боевой лист.", MasterSecret = "", RewardOrConsequence = "См. подробный блок боевого энкаунтера «Дезертиры разбитого гарнизона Востоколя».", LinkedCombatId = "cmb-deserters" },
                new EncounterItem { Id = "road-06", Category = "road", Min = 21, Max = 24, Title = "Проповедник «Истинных Хозяев» на перекрёстке", Mood = "mystery", Regions = "Тракт к Тирону · Вольск · Закатный Берег", Tags = new string[] { "illithids", "owls" }, AfterMinesOnly = false, Summary = "Оборванный жрец шепчет толпе крестьян о скором конце Империи и «даре освобождения разума».", SceneDetails = "На шесте рядом висит пустой череп с вырезанной спиралью. Проповедник говорит пугающе спокойным, ровным голосом, не моргая: «Когда звёзды погаснут, истинные хозяева снимут боль. Мы станем одним».", ChoicesOrChecks = "Религия Сл 13 — это НЕ вера Тёмных Земель и не культ Ильматера, его слова чужды богам Морриона. Проницательность Сл 14 — у двух слушателей в толпе уже помутнели зрачки.", MasterSecret = "Агент Иллитидов готовит паству к похищению в ближайшую шахту. Если на него надавить, его защитит случайный «купеческий охранник» в тёмно-синем плаще.", RewardOrConsequence = "У проповедника в сумке находят листовки и адрес склада гильдии «Взгляд Совы» в ближайшем городе.", LinkedCombatId = "" },
