                new EncounterItem { Id = "road-09", Category = "road", Min = 33, Max = 36, Title = "Карета с гербом рода Рейкваеров", Mood = "social", Regions = "Столичный тракт · Дорога Тирон — Фисль", Tags = new string[] { "owls", "empire" }, AfterMinesOnly = false, Summary = "Дорогая чёрно-золотая карета несётся в Тирон в окружении всадников «Ночных Крыльев».", SceneDetails = "Сквозь занавешенное окно мелькает перстень с золотой совой. Охранники в тёмно-синих сюрко и шлемах-кабассетах грубо сгоняют всех с дороги кнутами: «Дорогу Фактору Его Светлости!»", ChoicesOrChecks = "Восприятие Сл 15 — на запятках кареты привязан плоский свинцовый ящик с ледяным налётом и едва слышным шепотом внутри. История/Дворянство Сл 12 — узнать герб дома Рейкваеров («Взгляд Совы»).", MasterSecret = "В свинцовом футляре везут живую личинку-головастика иллитида для подпольной лаборатории в подземельях Тирона.", RewardOrConsequence = "Если уступить дорогу молча — герои запомнят карету; если завязать ссору — можно нарваться на засаду «Ночных Крыльев» через пару дней.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-10", Category = "road", Min = 37, Max = 40, Title = "Обрушенный мост и «плата кровью» на переправе", Mood = "hazard", Regions = "Река Тирий · Река Слёз · Мост Эльпида", Tags = new string[] { "vampires", "darklands" }, AfterMinesOnly = false, Summary = "Старый каменный мост обвален взрывом; в тумане ждёт молчаливый паромщик с длинным шестом.", SceneDetails = "Возле сломанных быков видны следы недавнего боя и обгорелые знамёна. Паромщик в глубоком капюшоне не берёт золота: «Монеты на том берегу не звенят. Капля живой крови на нос баржи — или ждите утра».", ChoicesOrChecks = "Религия/Тайная магия Сл 14 — распознать, что лодка зачарована ритуалом крови (вероятно, из Ноктариса или от Аманжа). Атлетика Сл 15 — перебраться вплавь по холодным развалинам с риском сноса.", MasterSecret = "Паромщик — дампир («Тень»), собирающий образцы крови путников для ритуалов отслеживания лорда Аманжа.", RewardOrConsequence = "Тот, кто отдал кровь, переправляется быстро и безопасно, но вампиры Аманжа получают его «след» на 1 неделю.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-11", Category = "road", Min = 41, Max = 44, Title = "Заброшенный постоялый двор и семья в погребе", Mood = "mystery", Regions = "Дорога у Тихого Лога · Тракт к Востоколю", Tags = new string[] { "illithids", "owls" }, AfterMinesOnly = false, Summary = "Двери трактира сорваны, но очаг ещё тёплый; из-под люка под половицами доносится детский плач.", SceneDetails = "Трактирщик с женой и дочкой прячутся за бочками с капустой. Они шепчут, что ночью приходили «господа в синих накидках и с мутными, как молоко, глазами» и увели всех постояльцев без единого крика.", ChoicesOrChecks = "Расследование Сл 13 — следы ведут не к лесу, а к старому колодцу за конюшней, где видны свежие верёвочные зарубки. Убеждение Сл 12 — семья опишет главного в золотой маске совы.", MasterSecret = "Жертв увели в подземный переход к ближайшей шахте для переработки в рабов Иллитидов.", RewardOrConsequence = "В тайнике хозяин хранит забытый прошлыми постояльцами набор отмычек и 1 свиток Обнаружения магии.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-12", Category = "road", Min = 45, Max = 48, Title = "Загнанный имперский гонец с Чёрной печатью", Mood = "social", Regions = "Любой крупный имперский тракт", Tags = new string[] { "empire", "darklands" }, AfterMinesOnly = false, Summary = "Измученный всадник падает вместе с загнанным в мыло конём прямо перед партией.", SceneDetails = "Его плащ изорван когтями, на боку сочащаяся чёрная рана. Он хрипит: «Востоколь пал… Дукс Аргентари исчез или предал… Везу депешу лично в Шпиль Ао и Сенат Тирона!»", ChoicesOrChecks = "Медицина Сл 13 — стабилизировать гонца и очистить рану от скверны. Внимательность Сл 14 — на горизонте уже скачут преследователи (либо гончие Тьмы, либо люди в масках).", MasterSecret = "В сумке две бумаги: официальный указ о падении Востоколя и тайная приписка инквизитора Мориса о «подозрительных поставках гильдии Рейкваеров».", RewardOrConsequence = "Если доставить письмо или спасти гонца — герои получают рекомендацию при дворе Тирона и +100 зм награды от курьерской службы.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-13", Category = "road", Min = 49, Max = 52, Title = "Боевой энкаунтер: Патруль Тёмных Земель", Mood = "combat", Regions = "Окрестности Востоколя, Корна, Закатного Берега", Tags = new string[] { "darklands" }, AfterMinesOnly = false, Summary = "Земля под сапогами темнеет и воняет гнилью — из кювета поднимаются покрытые коркой мертвецы.", SceneDetails = "Во главе отряда — сгорбленный Ученик-некромант с костяным посохом, перебирающий чётки и что-то выискивающий с помощью компаса скверны.", ChoicesOrChecks = "Прямой бой или засада на некроманта до того, как он поднимет подмогу.", MasterSecret = "", RewardOrConsequence = "См. подробный блок боевого энкаунтера «Авангард Тёмных Земель».", LinkedCombatId = "cmb-darklands" },
                new EncounterItem { Id = "road-14", Category = "road", Min = 53, Max = 56, Title = "Придорожная таверна «Сломанный рог»", Mood = "social", Regions = "Тирренгард · Центральный тракт · Вольск", Tags = new string[] { "empire", "illithids", "orcs" }, AfterMinesOnly = false, Summary = "Шумное, пропахшее луком и дешёвым пивом место, где сходятся слухи со всего континента.", SceneDetails = "За столами спорят наёмники из Бастиона Служения, торговцы из Вольска и уставшие ополченцы. Хозяин травит байки про пропавший отряд в Тихом Логе и слухи о восстании орков Зорга на севере.", ChoicesOrChecks = "Харизма (Убеждение/Обман Сл 12) или 2 золотых за выпивку — узнать до 3 свежих слухов о войне, Востоколе и контрабанде Взгляда Совы. Внимательность Сл 15 — в углу сидит странный человек в тёмных очках, не притронувшийся к элю.", MasterSecret = "Один из посетителей — агент Партии «Белых» дуксы Анастасии Тирронской, скупающий сведения о передвижениях армии.", RewardOrConsequence = "Безопасная ночёвка, свежая карта трактов и зацепка на побочный квест в Тихом Логе или Вольске.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-15", Category = "road", Min = 57, Max = 60, Title = "Бескровный труп на обочине", Mood = "mystery", Regions = "Тракты у Фисля, Порта Крови, Тирренгарда", Tags = new string[] { "vampires" }, AfterMinesOnly = false, Summary = "На теле нет следов драки или грабежа — только два аккуратных прокола на шее.", SceneDetails = "Погибший — молодой курьер или дворянин. Кошель полон серебра, клинок не вынут из ножен, лицо бледное как мел, ни капли крови на траве.", ChoicesOrChecks = "Расследование/Медицина Сл 13 — смерть наступила не более 3 часов назад; вампир не оставил укус «грязным», как ноктарисские дикари, а выпил жертву чисто, как элита Высшей Крови.", MasterSecret = "В отвороте сапога убитого спрятана шифровка для фактора Взгляда Совы — кто-то из слуг Аманжа уже охотится на связных гильдии.", RewardOrConsequence = "1 обычное зелье лечения, 1 слиток чистого серебра (хватит на посеребрение оружия или 25 зм).", LinkedCombatId = "" },
                new EncounterItem { Id = "road-16", Category = "road", Min = 61, Max = 64, Title = "Боевой энкаунтер: Ночная стая Аманжа", Mood = "combat", Regions = "Любой тракт (ночью или в сумерках)", Tags = new string[] { "vampires" }, AfterMinesOnly = true, Summary = "С ветвей бесшумно падают тени в чёрных плащах — слуги отколовшегося лорда-вампира пришли за вами.", SceneDetails = "Их глаза горят холодным рубиновым светом, а на брошах — перечёркнутая печать Ковена Ноктариса.", ChoicesOrChecks = "Бой или отступление к огню/освящённому месту. Переход в боевой лист.", MasterSecret = "", RewardOrConsequence = "См. подробный блок боевого энкаунтера «Ночная стая лорда Аманжа».", LinkedCombatId = "cmb-vampires" },
                new EncounterItem { Id = "road-17", Category = "road", Min = 65, Max = 68, Title = "Разрушенная часовня Старого Мориона", Mood = "omen", Regions = "Южный тракт к Бастиону Служения · Граница с Эльмаэлем", Tags = new string[] { "illithids", "empire" }, AfterMinesOnly = false, Summary = "Поросшие плющом руины храма времён Старой Империи, где воздух дрожит от статического напряжения.", SceneDetails = "На алтаре лежит разбитый символ Ао и свежие фиолетовые лепестки. Прикоснувшийся к камню слышит низкий зов и видит короткое видение: гигантский немигающий фиолетовый глаз под слоем чёрной земли, смотрящий вверх.", ChoicesOrChecks = "Спасбросок Мудрости Сл 13 — выдержать ментальный отголосок. Религия Сл 14 — благословить алтарь, чтобы получить краткое убежище на ночь (нежить не войдёт).", MasterSecret = "Под часовней проходит древний обрушенный туннель, соединявший подземелья старого Мориона с сетью Иллитидов.", RewardOrConsequence = "Долгосрочное вдохновение / защита от первого испуга на следующий день после очищения алтаря.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-18", Category = "road", Min = 69, Max = 72, Title = "Военный обоз Охотников на нежить", Mood = "social", Regions = "Дороги Закатного Берега · Тирренгард · Северный тракт", Tags = new string[] { "empire", "vampires", "darklands" }, AfterMinesOnly = false, Summary = "Укреплённый фургон с коваными решётками и факелами везёт припасы на передовую.", SceneDetails = "Возницы в кожаных плащах с серебряными клёпками и знаком Ордена Охотников на нежить (или паладинов Хельма сэра Мориса) готовы торговать с надёжными путниками.", ChoicesOrChecks = "Убеждение Сл 13 — убедить их поделиться военным запасом по божеской цене, если рассказать о встреченных тварях или показать трофей из Тёмных Земель.", MasterSecret = "Старший охотник жалуется, что в Тироне кто-то специально задерживает выплаты Ордену и тормозит поставки серебра через Сенат.", RewardOrConsequence = "В продаже: посеребрённые болты/стрелы (до 20 шт.), святая вода (2 флакона), чесночные связки и карты патрулей.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-19", Category = "road", Min = 73, Max = 76, Title = "Пьяный отпрыск Сената и вызов на дуэль", Mood = "social", Regions = "Подступы к Тирону · Фисленские дороги · Голдстенд", Tags = new string[] { "empire" }, AfterMinesOnly = false, Summary = "Юный дворянин с двумя слугами перегораживает дорогу и ищет повода доказать свою «доблесть».", SceneDetails = "Он в бархате Партии «Белых», навеселе, размахивает дорогой рапирой и кричит: «Я племянник сенатора, а вы — грязные наёмники! Защищайтесь или целуйте сапог!»", ChoicesOrChecks = "Убеждение/Обман Сл 12 — сбить спесь шуткой или пристыдить войной под Востоколем. Дуэль до первой крови — легко обезоружить без убийства.", MasterSecret = "Мальчишка на самом деле сбежал от призыва по Указу Императора и до смерти боится, что его отправят в мясорубку под Закатным Берегом.", RewardOrConsequence = "Если не убивать, а благородно проучить — он платит 30 зм «за молчание» и может стать полезным связным в Сенате Тирона.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-20", Category = "road", Min = 77, Max = 80, Title = "«Улыбающийся» крестьянин на развилке", Mood = "mystery", Regions = "Окрестности Тихого Лога · Дорога к Корну", Tags = new string[] { "illithids" }, AfterMinesOnly = false, Summary = "Одинокий селянин стоит под дождём с неестественно широкой, не сходящей с лица улыбкой.", SceneDetails = "Он не чувствует холода, говорит слишком ровно и вежливо: «Путники устали. Внизу тепло. Хозяин ждёт гостей, пойдёмте со мной короткой тропой к шахте».", ChoicesOrChecks = "Медицина/Проницательность Сл 12 — зрачки расширены, кожа в области затылка воспалена (след импланта или психического подчинения). Запугивание не действует — он не чувствует страха.", MasterSecret = "Если тихо проследить за ним на расстоянии (Скрытность Сл 13), он выведет прямо к замаскированному входу в шахту Иллитидов.", RewardOrConsequence = "Ключевая наводка на подземное логово; попытка «расколдовать» его без магии вызовет психический крик и призыв 1 Пожирателя разума.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-21", Category = "road", Min = 81, Max = 84, Title = "Древний тортл-паломник с картой миражей", Mood = "social", Regions = "Южный Предел · Дорога к Бастиону Служения", Tags = new string[] { "wild" }, AfterMinesOnly = false, Summary = "У обочины сидит пожилой прямоходящий черепах и аккуратно рисует углём дорожный этюд.", SceneDetails = "Представляется странствующим художником, ищущим редкие пигменты (на самом деле родственник или знакомый Аппы из легендарного «Оазиса Наслаждений»).", ChoicesOrChecks = "Харизма (Выступление/Убеждение Сл 12) — обменяться историями о подвигах или подарить красивую книгу/дневник для «библиотеки под пальмой».", MasterSecret = "Тортлы чувствуют искривления ткани реальности: он честно предупредит, что «под землёй под ногами кто-то поёт неправильную песню — не звёздную, а холодную, как щупальца».", RewardOrConsequence = "Дарит горсть «сладких ягод Юи» (действуют как 2 зелья малого исцеления или снимают 1 уровень истощения).", LinkedCombatId = "" },
                new EncounterItem { Id = "road-22", Category = "road", Min = 85, Max = 88, Title = "Агитатор и ночные поджигатели Вольска", Mood = "hazard", Regions = "Дороги вокруг Вольска · Речной тракт Тирия", Tags = new string[] { "antihi" }, AfterMinesOnly = false, Summary = "У придорожного алтаря стихий Коссута или Истишии разгорается драка с факелами.", SceneDetails = "Четверо человек в серых плащах с листовками «Антихов» пытаются разбить статую и сжечь часовню, крича: «Ваша вера в стихии накликала бури и падение Востоколя!» Рядом раненый послушник Хранителей Вольска.", ChoicesOrChecks = "Убеждение Сл 15 — утихомирить толпу до пожара, либо силовой разгон (см. «Фанатики-поджигатели Антихов»).", MasterSecret = "Пачки свежих газет пахнут дорогой типографской краской из Тирона или Фисля — кто-то специально спонсирует радикалов Антиха Иоганна.", RewardOrConsequence = "Благодарность Хранителей Вольска (бесплатный проход на речную баржу и рекомендация к одному из 4 храмов).", LinkedCombatId = "" },
                new EncounterItem { Id = "road-23", Category = "road", Min = 89, Max = 92, Title = "«Предатель Крови» у дорожного костра", Mood = "social", Regions = "Северная Марка · Дорога к Нодгарду и Крон-Дару", Tags = new string[] { "orcs" }, AfterMinesOnly = false, Summary = "Молчаливый великан в плаще с капюшоном чинит ось телеги; под капюшоном — спиленные орчьи клыки.", SceneDetails = "Он не ищет боя и тихо говорит на ломаном общем наречии: «Не трогайте меня — я ушёл. Кровавые Кочевники проснулись. Если пойдёте севернее без стали и глаз — Зорг сотрёт вас в порошок».", ChoicesOrChecks = "Проницательность Сл 12 — он не врёт и не шпион, он действительно «Предатель Крови». За монету или хлеб нарисует безопасную горную тропу мимо постов хобгоблинов.", MasterSecret = "Он сбежал от Когтя Ивакуры не просто от крови — «в самом низу под горой что-то шепчет голосом, от которого даже орки сходят с ума».", RewardOrConsequence = "Преимущество на все проверки Скрытности/Выживания в Северной Марке на 3 дня.", LinkedCombatId = "" },
                new EncounterItem { Id = "road-24", Category = "road", Min = 93, Max = 96, Title = "Боевой энкаунтер: Зачистка «Ночных Крыльев»", Mood = "combat", Regions = "Любой торговый тракт или портовая дорога", Tags = new string[] { "owls", "illithids" }, AfterMinesOnly = false, Summary = "Впереди перевёрнутая повозка, а вокруг неё — пять фигур в тёмно-синих сюрко с золотой совой.", SceneDetails = "Они только что добили случайного свидетеля, вскрывшего их ящик. Увидев отряд, офицер поднимает арбалет: «Никто не должен уйти с этой дороги».", ChoicesOrChecks = "Тактический бой в темноте/тумане или отчаянный блеф под агентов Рейкваеров (Обман Сл 17).", MasterSecret = "", RewardOrConsequence = "См. подробный блок боевого энкаунтера «Зачистка Ночных Крыльев».", LinkedCombatId = "cmb-owls-wings" },
                new EncounterItem { Id = "road-25", Category = "road", Min = 97, Max = 100, Title = "МИРОВОЙ БОСС: Встреча с посланцем Тьмы на тракте", Mood = "boss", Regions = "Любой опасный тракт", Tags = new string[] { "vampires", "darklands", "orcs" }, AfterMinesOnly = false, Summary = "Событие масштаба кампании — на дороге появляется фигура, с которой нельзя просто подраться в лоб.", SceneDetails = "В зависимости от региона на пути оказывается: Белуатье (правая рука Аманжа, если после пролога), Боевой Бехолдер Тёмных Земель (у Востоколя/Западного фронта) или разведка Зорга (на Севере).", ChoicesOrChecks = "Выживание, скрытность, переговоры или отчаянное бегство. Переход в лист Боссов.", MasterSecret = "", RewardOrConsequence = "См. блок Мировых боссов (Зорг, Бехолдер или Белуатье по региону).", LinkedCombatId = "cmb-boss-beluatye" },
                new EncounterItem { Id = "wild-01", Category = "wild", Min = 1, Max = 4, Title = "Гиблая топь и следы культа «Детей Ильматер»", Mood = "hazard", Regions = "Болота Юго-Востока · Окрестности павшего Востоколя", Tags = new string[] { "darklands", "wild" }, AfterMinesOnly = false, Summary = "Тропа пропадает в зловонной жиже, где торчат сгнившие тотемы и кости.", SceneDetails = "Воздух тяжёлый, вода местами пузырится чёрной пеной от соседства с порталом Тёмных Земель. На сухих кочках висят обрывки выцветших тряпок культа Сафиона Старообрядца.", ChoicesOrChecks = "Выживание Сл 13 — провести отряд по твёрдым кочкам без потери дня и сапог. При провале — 1 уровень истощения или потеря случайного припаса в трясине.", MasterSecret = "В одной из сумок под корнями можно найти старую записку Сафиона о «голосах, которые приказали открыть путь внизу».", RewardOrConsequence = "Уцелевший герметичный футляр со свитком Защиты от зла и добра.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-02", Category = "wild", Min = 5, Max = 8, Title = "Стадо оленей с третьим глазом", Mood = "omen", Regions = "Граница Эльмаэля · Леса у Гринока · Лес Предательств", Tags = new string[] { "illithids", "wild" }, AfterMinesOnly = false, Summary = "Между сосен пасётся стадо белых оленей — но у вожака посреди лба блестит моргающее третье око.", SceneDetails = "Звери абсолютно бесшумны и синхронно смотрят на партию. Если хотя бы одного ранить или убить — из раны вместо крови валит едкий фиолетовый дым, и в голове каждого звучит резкий звон.", ChoicesOrChecks = "Природа Сл 14 — это не мутация Тёмных Земель (там были бы хитин и костяные наросты), а психическое искажение. Спасбросок Телосложения Сл 12 при вдыхании дыма.", MasterSecret = "Стадо прошло через подземный родник, отравленный псионической слизью из-под Тихого Лога.", RewardOrConsequence = "Если не убивать, а проследить за стадом — выведет к чистому ручью или эльфийской тропе.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-03", Category = "wild", Min = 9, Max = 12, Title = "Светящаяся грибная поляна и ночные споры", Mood = "mystery", Regions = "Тёмные чащи · Предгорья Крон-Дара · Подземелья", Tags = new string[] { "wild", "illithids" }, AfterMinesOnly = false, Summary = "Ночью поляна сияет голубовато-лиловым светом гигантских грибов размером с тележное колесо.", SceneDetails = "В центре поляны лежат свежие остатки зверей, но без ран — они просто заснули и высохли. По краям растут редкие алхимические шляпки.", ChoicesOrChecks = "Природа Сл 13 — отличить целебные лунные грибы (годны для зелий) от псионических спор. Телосложение Сл 13 — не уснуть под сладким запахом.", MasterSecret = "Глубоко под грибницей проходит туннель гримлоков, собирающих добычу для Иллитидов.", RewardOrConsequence = "Ингредиенты на 2 зелья лечения или 40 зм у алхимиков Фисля/Вольска.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-04", Category = "wild", Min = 13, Max = 16, Title = "Заброшенная шахта с низким гулом", Mood = "mystery", Regions = "Предгорья · Тихий Лог · Большой Каньон", Tags = new string[] { "illithids", "wild" }, AfterMinesOnly = false, Summary = "Из-под заросшего входа в старую штольню тянет тёплым сырым воздухом и слышен мерный пульсирующий гул.", SceneDetails = "Ржавые вагонетки оставлены много лет назад, но на рельсах видны свежие следы волочения ящиков с клеймом «В.С.». У входа в сторожке валяется рваный чертёж штреков.", ChoicesOrChecks = "Внимательность Сл 13 — услышать, что гул идёт ритмом сердцебиения каждые 6 секунд. Расследование Сл 12 — забрать карту старых галерей.", MasterSecret = "Одна из вспомогательных шахт, куда «Взгляд Совы» сгружает пленных и кристаллы для Иллитидов.", RewardOrConsequence = "Старая карта нижних штреков (даёт преимущество против ловушек и блужданий под землёй).", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-05", Category = "wild", Min = 17, Max = 20, Title = "Отряд Охотников на нежить на привале", Mood = "social", Regions = "Закатный Берег · Рубежи Востоколя · Каньон Погибели", Tags = new string[] { "empire", "darklands", "vampires" }, AfterMinesOnly = false, Summary = "Трое измотанных бойцов в серебряных перевязях жгут костёр из сухих костей и точат колья.", SceneDetails = "Они из Ордена Охотников на нежить герцогини Изабеллы Корво. Только что отбили нападение упырей и собираются обратно к границе.", ChoicesOrChecks = "Медицина Сл 12 или помощь провизией — завоевать доверие старшего охотника. Он поделится тактикой против «новой нежити с чёрной коркой, которая не боится святых символов».", MasterSecret = "Охотники заметили, что отколовшиеся вампиры Аманжа сами убивают некромантов Тёмных Земель на западной границе.", RewardOrConsequence = "Дарят колчан из 10 посеребрённых стрел и 1 флакон святой воды.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-06", Category = "wild", Min = 21, Max = 24, Title = "Боевой энкаунтер: Охота Тёмных Земель", Mood = "combat", Regions = "Любая дикая местность", Tags = new string[] { "darklands" }, AfterMinesOnly = false, Summary = "Из оврага с хрустом костей выползает разведгруппа некроманта.", SceneDetails = "Деревья вокруг места схватки уже покрыты чёрной плесенью, птицы улетели за версту.", ChoicesOrChecks = "Бой или попытка обойти врага по кронам/скалам (Скрытность Сл 14).", MasterSecret = "", RewardOrConsequence = "См. подробный блок боевого энкаунтера «Авангард Тёмных Земель».", LinkedCombatId = "cmb-darklands" },
                new EncounterItem { Id = "wild-07", Category = "wild", Min = 25, Max = 28, Title = "Ведьмин круг фей и сбой времени", Mood = "mystery", Regions = "Глухие леса Эльмаэля · Лес Предательств", Tags = new string[] { "wild", "elves" }, AfterMinesOnly = false, Summary = "Идеальное кольцо из белых цветов и серебристого мха, внутри которого воздух звенит как стекло.", SceneDetails = "Внутри круга на камне лежит блестящий кинжал из фейского серебра или старый эльфийский медальон. Стоит ступить внутрь — тени деревьев бегут с пугающей скоростью.", ChoicesOrChecks = "Магия/Природа Сл 14 — понять, что время внутри бежит в 10 раз медленнее/быстрее внешнего мира (10 минут внутри = сутки снаружи). Спасбросок Харизмы Сл 13 против чар.", MasterSecret = "Шёпот фей боится «людей без снов» (иллитидов) и готов шепнуть тайное имя одного из врагов в обмен на яркое воспоминание.", RewardOrConsequence = "Серебряный кинжал +1 против фей/нежити или потеря нескольких часов/суток похода.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-08", Category = "wild", Min = 29, Max = 32, Title = "Разрушенная дозорная башня с барельефом щупалец", Mood = "mystery", Regions = "Руины Старого Мориона · Южный Предел · Большой Каньон", Tags = new string[] { "illithids" }, AfterMinesOnly = false, Summary = "Полуобвалившаяся башня времён до Катаклизма, подвал которой не тронут временем.", SceneDetails = "Под слоем свежей копоти видны древние каменные плиты. На центральной плите высечено гуманоидное существо с длинной головой и четырьмя щупальцами у рта, перед которым на коленях стоят люди Старого Мориона.", ChoicesOrChecks = "История Сл 14 — барельеф гораздо старше Катаклизма, он высечен ещё до распада Империи Морион, но кто-то недавно счищал с него мох.", MasterSecret = "Прямое доказательство для партии, что Иллитиды спали под континентом ещё со времён Старого Мориона, а не пришли из портала Тёмных Земель.", RewardOrConsequence = "Тайник под плитой: 25 золотых древней чеканки (50 зм коллекционерам в Фисле) и старая карта.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-09", Category = "wild", Min = 33, Max = 36, Title = "Боевой энкаунтер: Охотники из-под земли", Mood = "combat", Regions = "Пещеры, скалы, тёмные леса", Tags = new string[] { "illithids" }, AfterMinesOnly = true, Summary = "Земля под кустами проваливается, и оттуда бросаются слепые чудовища, выслеживающие разум.", SceneDetails = "Воздух резко холодеет, во рту появляется вкус озона и крови.", ChoicesOrChecks = "Проверка Инициативы с возможным эффектом неожиданности при провале Восприятия Сл 14.", MasterSecret = "", RewardOrConsequence = "См. подробный блок боевого энкаунтера «Твари Психического Поиска».", LinkedCombatId = "cmb-illithid-beasts" },
                new EncounterItem { Id = "wild-10", Category = "wild", Min = 37, Max = 40, Title = "Безымянное кладбище с вырытыми могилами", Mood = "mystery", Regions = "Окрестности Корна · Земли за Востоколем", Tags = new string[] { "darklands", "vampires" }, AfterMinesOnly = false, Summary = "Десятки каменных плит без единого имени — и каждая могила раскопана изнутри… или аккуратно вскрыта сверху.", SceneDetails = "Земля у ям не разбросана хаотично, как при подъёме нежити, а сложена ровными кучками. Видны следы сапог в железных подковах и следы колёс тяжёлой телеги.", ChoicesOrChecks = "Расследование Сл 13 — свежие трупы увозили специально! Но часть могил пуста слишком давно — будто здесь уже бушевала старая война или некромантия времён архилича Вальгула.", MasterSecret = "Тела скупали подрядчики для некромантов или опытов по пересадке мозговых личинок.", RewardOrConsequence = "В забытом саркофаге можно найти фамильный серебряный перстень (35 зм) или старый ключ от катакомб.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-11", Category = "wild", Min = 41, Max = 44, Title = "Пещера отшельника из Круга Небесных Тел", Mood = "social", Regions = "Горы · Лесные ущелья · Граница Тирона", Tags = new string[] { "empire", "illithids" }, AfterMinesOnly = false, Summary = "Слепой друид в плаще из мха разложил на камне медные астролябии и шепчет пророчества.", SceneDetails = "Он отвернулся от столичных Садов Селунэ архидруидки Гиацинтии, но всё ещё служит Селунэ. Его пустые глазницы обращены к небу: «Драконы звёзд молчат. Над нами смотрят не туда. Свет луны бьётся о купол, а под ногами пустота, которая учится думать».", ChoicesOrChecks = "Религия/Магия Сл 13 — друид предупреждает о великом обмане внутри Тирона и советует «не верить тем, кто носит золото совы на синем сукне».", MasterSecret = "Даже архидруидка Гиацинтия не всё видит — ментальные экраны Иллитидов глушат её предсказания над Востоколем и Тихим Логом.", RewardOrConsequence = "Друид благословляет отряд (сопротивление первому проклятию/очарованию на 48 часов) и лечит лёгкие раны.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-12", Category = "wild", Min = 45, Max = 48, Title = "Боевой энкаунтер: Ночной дозор эльфов Эльмаэля", Mood = "combat", Regions = "Леса близ Гринока · Теневая Твердыня · Южная граница", Tags = new string[] { "elves" }, AfterMinesOnly = false, Summary = "Среди ветвей щёлкают тетивы — следопыты Теневой Твердыни окружили непрошеных гостей.", SceneDetails = "Лидер дозора говорит с презрением: «Имперцы? Или псы Гиацинтии-предательницы? У вас три вдоха, чтобы бросить сталь на землю».", ChoicesOrChecks = "Дипломатия (Убеждение Сл 15) или схватка в лесных иллюзиях.", MasterSecret = "", RewardOrConsequence = "См. подробный блок боевого энкаунтера «Ночной дозор Теневой Твердыни».", LinkedCombatId = "cmb-elven-raiders" },
                new EncounterItem { Id = "wild-13", Category = "wild", Min = 49, Max = 52, Title = "Дерево, искажённое чужой силой", Mood = "omen", Regions = "Леса Эльмаэля · Тихий Лог · Серебрянка", Tags = new string[] { "illithids" }, AfterMinesOnly = false, Summary = "Огромный дуб в лесу изогнут в невозможную спираль, но на нём нет ни гнили, ни трупных пятен Тёмных Земель.", SceneDetails = "Кора дерева стала гладкой, влажной и тёмно-лиловой, напоминающей мягкую кожу или мозговые извилины. Вокруг не поют птицы, а при прикосновении рука чувствует слабый тёплый пульс.", ChoicesOrChecks = "Природа/Магия Сл 14 — чёткое отличие: Тёмные Земли сжигают и чернят природу, а ЭТА сила переписывает живую материю, превращая дерево в живой ретранслятор.", MasterSecret = "Прямой намёк на присутствие Иллитидов: их псионические кристаллы в корнях перестраивают лес вокруг скрытых баз.", RewardOrConsequence = "Если срубить и забрать осколок лиловой коры — алхимики и Круг Небесных Тел заплатят 60 зм за образец.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-14", Category = "wild", Min = 53, Max = 56, Title = "Охотник из клана «Пронзительная Стрела»", Mood = "social", Regions = "Леса вокруг Гринока · Река Слёз", Tags = new string[] { "wild", "elves", "illithids" }, AfterMinesOnly = false, Summary = "Измождённый следопыт в зелёном плаще сидит в засаде и просит не шуметь.", SceneDetails = "Боец из отряда Дерека Вейна (Гринок) уже третий день ищет двоих пропавших товарищей. Он клянётся, что это не эльфы Теневой Твердыни — те хотя бы забирают добычу по договору, а здесь «люди пропадают вместе с собаками, не оставив следа крови».", ChoicesOrChecks = "Выживание Сл 13 — помочь ему прочитать следы (они обрываются у старого провала в земле или берега Реки Слёз).", MasterSecret = "Охотников Гринока забирают либо отродья Аманжа, либо группы «Взгляда Совы» для экспериментов и пополнения рабов.", RewardOrConsequence = "Проводник по лесу, 10 отличных охотничьих стрел и доверие Дерека Вейна в Гриноке.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-15", Category = "wild", Min = 57, Max = 60, Title = "Боевой энкаунтер: Разбойники или Дезертиры в засаде", Mood = "combat", Regions = "Лесные тропы и горные перевалы", Tags = new string[] { "empire", "wild" }, AfterMinesOnly = false, Summary = "Треснула ветка под сапогом дозорного — впереди лагерь беглых солдат или лесных налётчиков.", SceneDetails = "Если это севернее — дезертиры из Востоколя; если ближе к югу/Западу — отчаявшиеся бандиты из разорённых деревень.", ChoicesOrChecks = "Бой, скрытный обход (Скрытность Сл 13) или переговоры.", MasterSecret = "", RewardOrConsequence = "См. блок «Мародёры трактов» или «Дезертиры Востоколя».", LinkedCombatId = "cmb-bandits" },
                new EncounterItem { Id = "wild-16", Category = "wild", Min = 61, Max = 64, Title = "Белый туман и шёпот имён", Mood = "hazard", Regions = "Закатный Берег · Болота · Горные долины", Tags = new string[] { "wild", "vampires", "darklands" }, AfterMinesOnly = false, Summary = "Молочная пелена ложится за минуту — не видно даже вытянутой руки.", SceneDetails = "В тумане искажаются расстояния и голоса: товарищ в трёх шагах звучит так, будто кричит из колодца. Порой сквозь вату мелькает чей-то высокий силуэт или слышен плач из-под земли.", ChoicesOrChecks = "Выживание Сл 13 — не сбиться с маршрута. При провале — партия блуждает 4 часа и выходит к случайному опасному месту (повторный бросок по дикой таблице с +20 или засада волков/упырей).", MasterSecret = "Туман часто используют вампиры Аманжа и нежить Закатного Берега для скрытых перемещений днём.", RewardOrConsequence = "Успешная навигация позволяет наткнуться в тумане на брошенный вьюк с припасами (сухой паёк на 4 дня).", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-17", Category = "wild", Min = 65, Max = 68, Title = "Ущелье гигантского паука и странные коконы", Mood = "hazard", Regions = "Тёмные леса · Большой Каньон · Подступы к Ноктарису", Tags = new string[] { "wild", "vampires" }, AfterMinesOnly = false, Summary = "Узкая расщелина затянута прочными, как тросы, серебристыми нитями паутины.", SceneDetails = "Среди коконов висят два погибших наёмника и живой торговец, который едва шевелится. Гигантский охотничий паук (размером с лошадь) спускается сверху почти бесшумно.", ChoicesOrChecks = "Скрытность Сл 14 — срезать живого пленника и проскользнуть мимо спящего хищника, либо бой с 1 Гигантским фазовым пауком.", MasterSecret = "В Ноктарисе вампиры выращивают подобных пауков ради прочных шёлковых тканей; паутина может стоить денег в Порту Крови или Фисле.", RewardOrConsequence = "Рулон прочнейшей паутины (50 зм), спасённый купец и яд паука на 3 дозы.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-18", Category = "wild", Min = 69, Max = 72, Title = "Руины лунного святилища Селунэ", Mood = "mystery", Regions = "Граница Тирона · Окрестности Тирренгарда · Южный Предел", Tags = new string[] { "empire", "elves" }, AfterMinesOnly = false, Summary = "Беломраморная колоннада с чашей, в которой до сих пор собирается удивительно чистая лунная вода.", SceneDetails = "Надписи на старом общем и эльфийском говорят о мире до раскола Эльмаэля и Круга Небесных Тел. На полу сохранилась сложная мозаика созвездий.", ChoicesOrChecks = "Религия/Магия Сл 13 — восстановить прерванный узор звёзд в чаше или оставить скромную жертву серебром.", MasterSecret = "Осквернение святилища приведёт к гневу друидов Гиацинтии, а восстановление покажет на воде отражение ближайшего очага порчи.", RewardOrConsequence = "Благословение Селунэ: ночной отдых в руинах считается за полный с +1d6 временных хитов и без случайных атак.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-19", Category = "wild", Min = 73, Max = 76, Title = "Внезапная гроза и обвал, открывший ход", Mood = "hazard", Regions = "Горы Ивакура · Предгорья Крон-Дара · Каньоны", Tags = new string[] { "wild", "illithids" }, AfterMinesOnly = false, Summary = "Молнии бьют в соседний гребень, ливень смывает тропу, а оползень обнажает скрытый спуск.", SceneDetails = "Чтобы не замерзнуть и не получить уровень истощения, отряд вынужден искать укрытие — и за рухнувшим валуном обнаруживается древняя кладка тайной шахты или контрабандистского схрона.", ChoicesOrChecks = "Телосложение Сл 13 против ледяного ливня (иначе 1 уровень истощения). Внутри хода — Внимательность Сл 14 на старую механическую ловушку дварфов.", MasterSecret = "Штольня ведёт либо в обход постов орков в Северной Марке, либо к тайному лифту контрабандистов Взгляда Совы.", RewardOrConsequence = "Сухой ночлег, ящик дварфийских факелов и 15–30 зм в старой походной шкатулке.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-20", Category = "wild", Min = 77, Max = 80, Title = "Психическая атака «Шёпот из бездны»", Mood = "omen", Regions = "Любая дикая местность рядом с шахтами или руинами", Tags = new string[] { "illithids" }, AfterMinesOnly = false, Summary = "На секунду мир теряет краски, в ушах звенит, и каждый герой слышит свой же голос у себя в затылке.", SceneDetails = "Голос шепчет самое сокровенное сожаление или страх каждого персонажа и тихо спрашивает: «Ты всё ещё думаешь, что идёшь сам? Мы уже внутри стен».", ChoicesOrChecks = "Спасбросок Мудрости Сл 14. Провалившие получают 1d6 психического урона (или кошмар без полноценного восстановления на привале) и смутное чувство направления, откуда шёл сигнал.", MasterSecret = "Где-то в пределах 10 миль работает Старший Мозг или мощный псионический маяк Иллитидов, сканирующий носителей артефактов.", RewardOrConsequence = "Успешно прошедшие спасбросок запоминают точное направление к источнику сигнала.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-21", Category = "wild", Min = 81, Max = 84, Title = "Песчаная буря и миражи «Всемирного Панциря»", Mood = "hazard", Regions = "Южный Предел · Пустыня Закатного Берега", Tags = new string[] { "wild" }, AfterMinesOnly = false, Summary = "Горизонт чернеет от поднятого песка, а среди вихрей на секунду мерещатся зелёные пальмы и водопады.", SceneDetails = "Это отголосок барьера легендарного «Оазиса Наслаждений» — и смертоносная буря, выносящая из пустыни вещи погибших искателей.", ChoicesOrChecks = "Выживание Сл 14 — укрыться за скалой и не пойти за миражом. При провале — 1 уровень истощения от жажды и жара.", MasterSecret = "Именно такие бури забрасывают в оазис тортлов книги и дневники со всего континента.", RewardOrConsequence = "После бури песок обнажает скелет старого путешественника: дневник с заметкой о Бирюзовом Камне, фляга и хороший стальной клинок/компас.", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-22", Category = "wild", Min = 85, Max = 88, Title = "Волчий вой и поминальные черепа Ивакуры", Mood = "omen", Regions = "Северная Марка · Подступы к Нодгарду и Горе Ивакура", Tags = new string[] { "orcs" }, AfterMinesOnly = false, Summary = "На границе видимости высится пирамида из черепов разного размера — от великанских до гоблинских.", SceneDetails = "Глазницы старых черепов едва заметно теплятся болотно-зелёным светом, а вокруг груды вытоптаны следы десятков окованных сапог. Наверху воткнуто свежее знамя Кровавых Кочевников.", ChoicesOrChecks = "Скрытность Сл 14 или Знание (История Сл 12) — это межевая отметка «Гнезда» Зорга. Приближаться — смертельный риск.", MasterSecret = "Кто-то из шаманов орды слышит зов снизу из-под Когтя Ивакуры — там пробуждается нечто древнее, не связанное с Тёмными Землями.", RewardOrConsequence = "Можно снять данные о численности отрядов орков и передать их дуксу Эберхарду фон Морозу в Нодгарде за солидную плату (75 зм).", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-23", Category = "wild", Min = 89, Max = 92, Title = "Внешнее кольцо запечатанных катакомб Корна", Mood = "mystery", Regions = "Окрестности Корна · Южнее Востоколя", Tags = new string[] { "darklands" }, AfterMinesOnly = false, Summary = "Среди обгорелых лесов открывается древний люк с оплавленными печатями древних князей.", SceneDetails = "Когда пал Корн, последние горожане спустились под землю — и замуровали выход изнутри, или кто-то запечатал его снаружи, чтобы «то, что внутри, не вышло вместе с демонами».", ChoicesOrChecks = "Расследование Сл 13 — на камне нацарапано свежей ногтевой бороздой: «Вальгул проснулся раньше них». Слышно слабое царапание с той стороны.", MasterSecret = "Возможный крючок в отдельное подземелье архилича Вальгула, который сам ненавидит демонов Тёмных Земель.", RewardOrConsequence = "У входа остался брошенный походный сундук стражника Корна (броня/щит или 30 зм).", LinkedCombatId = "" },
                new EncounterItem { Id = "wild-24", Category = "wild", Min = 93, Max = 96, Title = "Боевой энкаунтер: Диверсанты или Вампиры", Mood = "combat", Regions = "Любая дикая местность", Tags = new string[] { "vampires", "antihi", "owls" }, AfterMinesOnly = false, Summary = "Привал срывает внезапное нападение: в лесах у Вольска — поджигатели Антихов; в остальном мире — отродья Аманжа или «Ночные Крылья».", SceneDetails = "Подберите отряд врагов под регион нахождения партии.", ChoicesOrChecks = "Проверка Восприятия дозорного Сл 14 против засады.", MasterSecret = "", RewardOrConsequence = "См. боевой лист («Фанатики Антихов», «Ночная стая Аманжа» или «Ночные Крылья»).", LinkedCombatId = "cmb-antihi-cell" },
                new EncounterItem { Id = "wild-25", Category = "wild", Min = 97, Max = 100, Title = "МИРОВОЙ БОСС: Зорг Кровожадная Пасть", Mood = "boss", Regions = "Северная Марка (или Бехолдер на Западе / Белуатье после пролога)", Tags = new string[] { "orcs", "darklands", "vampires" }, AfterMinesOnly = false, Summary = "Земля дрожит под тяжёлой поступью величайшей угрозы региона.", SceneDetails = "На Севере перед героями вырастает разведывательная колонна самого Зорга «Кровожадной Пасти» с ограми и хобгоблинами. На Западе или у портала — боевой Бехолдер Тёмных Земель.", ChoicesOrChecks = "Прятки, маскировка, ловушки или немедленное отступление.", MasterSecret = "", RewardOrConsequence = "См. подробный блок Мировых боссов.", LinkedCombatId = "cmb-boss-zorg" },
                new EncounterItem { Id = "water-01", Category = "water", Min = 1, Max = 4, Title = "Кораблекрушение с ящиком фиолетовых кристаллов", Mood = "mystery", Regions = "Залив Фисля · Река Тирий · Побережье Тирренгарда", Tags = new string[] { "illithids", "owls" }, AfterMinesOnly = false, Summary = "На мели лежит расколотый когг без экипажа, а на обломках палубы прикован свинцовый ящик.", SceneDetails = "В трюме ни капли крови — только перевёрнутые стулья и судовой журнал с вырванными последними страницами. Внутри взломанного ящика слабо пульсируют гранёные фиолетовые кристаллы.", ChoicesOrChecks = "Магия Сл 13 — кристаллы работают как псионический усилитель, от них немеют пальцы. Расследование Сл 12 — на борту сохранилось замазанное смолой клеймо «Взгляда Совы».", MasterSecret = "Судно Рейкваеров везло кристаллы из Фисля в устье Тирия. Что-то внутри ящика «проснулось» и свело команду в воду.", RewardOrConsequence = "2 кристалла (стоят по 75 зм, но притягивают тварей Иллитидов), 20 зм в монетах Фисля и подзорная труба.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-02", Category = "water", Min = 5, Max = 8, Title = "Слишком приветливая рыбацкая деревня", Mood = "mystery", Regions = "Восточное побережье · Дельта Тирия · Фэльнюр", Tags = new string[] { "illithids" }, AfterMinesOnly = false, Summary = "На берегу горит десяток фонарей, пахнет сладкой выпечкой и сушёной рыбой, а жители не сводят с гостей одинаковых улыбок.", SceneDetails = "Старшина предлагает бесплатный ночлег в общем амбаре и сладкий травяной взвар. Дети молчат и двигаются синхронно. На шестах сушатся пустые сети — в воде у пристани нет ни одной живой рыбы.", ChoicesOrChecks = "Внимательность/Природа Сл 13 — сладкий запах идёт не от кухни, а от фиолетового ила в лодках. Проницательность Сл 14 — у всех жителей мутный взгляд и царапины за ухом.", MasterSecret = "Деревня уже порабощена подземным очагом Иллитидов (или их «головастиками» в колодце). Ночью жителей поведут в пещеру на приливе, а гостей попробуют усыпить взваром.", RewardOrConsequence = "Если вовремя сбежать или перехватить связного — герои находят карту подводного грота; если выпить взвар — Спасбросок Тел Сл 14 или сон.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-03", Category = "water", Min = 9, Max = 12, Title = "Боевой галеас Фисля и предупреждение о волне", Mood = "social", Regions = "Морские пути у Фисля · Западный рейд Тирренгарда", Tags = new string[] { "empire", "darklands" }, AfterMinesOnly = false, Summary = "Грозный галеас Светлейшей Республики с пушками и боевым магом на носу берет лодку партии на оклик.", SceneDetails = "Капитан-кондотьер в позолоченной кирасе проверяет документы и предупреждает: «Южнее Закатного Берега пошла новая волна нежити. Вчера видели чёрный металлический галеон без парусов!»", ChoicesOrChecks = "Убеждение Сл 12 — обменяться картами и новостями с суши (особенно о падении Востоколя — в Фисле за свежие разведданные платят).", MasterSecret = "Республика Фисль в панике из-за потери хлебной торговли с Востоколем, и три банковских дома уже нанимают авантюристов в обход Сената Тирона.", RewardOrConsequence = "Капитан дарит сигнальную ракету, карту рифов или покупает новости за 30 «фислей».", LinkedCombatId = "" },
                new EncounterItem { Id = "water-04", Category = "water", Min = 13, Max = 16, Title = "Боевой энкаунтер: Пираты и контрабандисты залива", Mood = "combat", Regions = "Залив Фисля · Устье Тирия · Мечта Караванщика", Tags = new string[] { "empire", "wild" }, AfterMinesOnly = false, Summary = "Быстроходная фелука без флага выходит из-за скалы и бросает абордажные кошки.", SceneDetails = "Голодные пираты и бывшие речные разбойники требуют весь груз провизии, эль и золото, угрожая сжечь такелаж.", ChoicesOrChecks = "Морской манёвр (Водный транспорт Сл 14), торг или абордажный бой.", MasterSecret = "", RewardOrConsequence = "См. боевой блок «Мародёры разорившихся трактов» (пиратская адаптация).", LinkedCombatId = "cmb-bandits" },
                new EncounterItem { Id = "water-05", Category = "water", Min = 17, Max = 20, Title = "Гигантский краб с рунами Старого Мориона", Mood = "hazard", Regions = "Мелководье · Побережье Фэльнюра · Острова у Закатного Берега", Tags = new string[] { "wild" }, AfterMinesOnly = false, Summary = "Из-под воды поднимается панцирь размером с карету, покрытый светящимися синими рунами защиты.", SceneDetails = "Существо не похоже на тварь скверны — это древний страж акватории времён Империи Морион. Он цепляется клешнями за киль, словно проверяет, нет ли на борту тёмной магии.", ChoicesOrChecks = "Магия/История Сл 13 — понять, что краб атакует только носителей некромантии/скверны или тех, кто первым ударит. Можно успокоить броском куска свежего мяса (Уход за животными Сл 12) или принять бой.", MasterSecret = "На его панцире выбит старый императорский пароль от затопленных маяков Старого Мориона.", RewardOrConsequence = "Если победить — 30 зм в виде редких рунных пластин панциря; если договориться/успокоить — краб отгоняет акул и приносит из глубин сундук с 20 зм.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-06", Category = "water", Min = 21, Max = 24, Title = "Маяк Фэльнюра и бой с «Чёрными парусами»", Mood = "combat", Regions = "Фэльнюр · Восточное море · Подступы к Порту Крови", Tags = new string[] { "vampires", "owls" }, AfterMinesOnly = false, Summary = "Смотритель маяка отчаянно мигает красным огнём — в бухте показался корабль с чёрными парусами без единого фонаря.", SceneDetails = "Корабль скользит почти бесшумно; на его носу — герб отколовшегося дома вампиров Аманжа (или перекупленная шхуна Ноктариса). Начинается погоня и абордаж при свете маяка.", ChoicesOrChecks = "Координация корабля (Водный транспорт / Атлетика Сл 14) ради удержания света маяка — яркий луч обжигает вампиров.", MasterSecret = "Корабль Аманжа выслеживает именно галеон «Взгляда Совы», шедший на час впереди партии.", RewardOrConsequence = "Переход в боевой лист «Ночная стая лорда Аманжа» на палубе или награда от смотрителя маяка (карта течений и 40 зм).", LinkedCombatId = "cmb-vampires" },
                new EncounterItem { Id = "water-07", Category = "water", Min = 25, Max = 28, Title = "Боевой энкаунтер: Чёрный галеон Тёмных Земель", Mood = "combat", Regions = "Море Скорби · Западное побережье у Закатного Берега", Tags = new string[] { "darklands" }, AfterMinesOnly = false, Summary = "На горизонте вырастает корпус из чёрного металла без вёсел и ветра — он идёт на воле некроманта.", SceneDetails = "Из бортовых люков вылетает шлюпка с восставшими трупами в чёрной корке и учеником-некромантом, а сам галеон готовит катапульту скверны.", ChoicesOrChecks = "Сбить абордажную группу и уйти в мелководье, куда тяжёлый железный галеон не пройдёт.", MasterSecret = "", RewardOrConsequence = "См. подробный блок «Авангард Тёмных Земель».", LinkedCombatId = "cmb-darklands" },
                new EncounterItem { Id = "water-08", Category = "water", Min = 29, Max = 32, Title = "Побережье мертвецов и фиолетовый прилив", Mood = "omen", Regions = "Безлюдные бухты · Острова между Фислем и Закатным Берегом", Tags = new string[] { "illithids", "darklands" }, AfterMinesOnly = false, Summary = "Вода у берега отливает маслянистым фиолетовым блеском, а на гальке лежат десятки мёртвых матросов и рыб.", SceneDetails = "Вода не пахнет гнилью — от неё веет холодным металлическим озоном. У выброшенных тел отсутствуют глаза, а кожа на черепах втянута внутрь.", ChoicesOrChecks = "Природа/Магия Сл 14 — в морской глубине под этим местом открыт либо подводный шлюз, либо упавший корабль Иллитидов.", MasterSecret = "Не пить воду и не умываться ею: Спасбросок Телосложения Сл 13, иначе ночные галлюцинации и психическое истощение.", RewardOrConsequence = "На спасшемся от крабов теле матроса находится водонепроницаемая трубка с картой торговых рейсов «Взгляда Совы».", LinkedCombatId = "" },
                new EncounterItem { Id = "water-09", Category = "water", Min = 33, Max = 36, Title = "Морской грот с фресками «Длинноголовых»", Mood = "mystery", Regions = "Скалистый берег · Устье у Тихого Лога · Архипелаг Фисля", Tags = new string[] { "illithids" }, AfterMinesOnly = false, Summary = "Во время отлива открывается низкий вход в пещеру, куда можно заплыть на лодке.", SceneDetails = "На влажных стенах — выцветшие, но подновлённые свежей краской фрески: гуманоиды с вытянутыми черепами и щупальцами принимают дары от капитанов в синих плащах с совами.", ChoicesOrChecks = "Религия/История Сл 13 — часть рисунков древняя, а свежие подписи сделаны на современном имперском языке (шифры портовых контор Тирренгарда и Фисля).", MasterSecret = "Секретный перевалочный пункт культистов иллитидов и факторов Взгляда Совы. Здесь прячут пленников перед погрузкой.", RewardOrConsequence = "Запрятанный сундук с двумя флаконами Дыхания под водой и 35 зм.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-10", Category = "water", Min = 37, Max = 40, Title = "Кладбище старых кораблей Мориона", Mood = "mystery", Regions = "Туманная отмель · Море Скорби · Южная лагуна", Tags = new string[] { "darklands", "wild" }, AfterMinesOnly = false, Summary = "Десятки обросших ракушками остовов торчат из воды, как ребра великана.", SceneDetails = "На корме полузатопленного галеона времён Старой Империи блестит окованный латунью сундук, но тёмная вода вокруг слабо колышется без ветра.", ChoicesOrChecks = "Внимательность Сл 13 — под водой шевелятся 3–4 утопленника. Можно дотянуться до сундука багром и верёвкой (Атлетика/Ловкость Сл 14) без шума, либо вступить в схватку с нежитью.", MasterSecret = "В сундуке, кроме золота, лежит судовой журнал времён Катаклизма, упоминающий о «Чёрном Обелиске в центре Тёмных Земель».", RewardOrConsequence = "65 зм старой чеканки, старинный компас (всегда указывает на север даже в тумане) и кусок лора Катаклизма.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-11", Category = "water", Min = 41, Max = 44, Title = "Мёртвый штиль и проклятие пресной воды", Mood = "hazard", Regions = "Открытое море · Большое озеро", Tags = new string[] { "wild", "antihi" }, AfterMinesOnly = false, Summary = "Ветер падает до нуля, паруса обвисают тряпками, а вода в бочках внезапно становится горькой и мутной.", SceneDetails = "Море зеркальное, как чёрное стекло. Жажда скручивает команду уже к полудню — на борту остаётся воды меньше чем на сутки. В трюме шуршат крысы.", ChoicesOrChecks = "Выживание/Природа Сл 13 — соорудить опреснитель из парусины и котла (или очистить воду заклинанием/ритуалом Истишии). Иначе каждый член отряда получает 1 уровень истощения к концу дня.", MasterSecret = "Иногда такой штиль вызывают радикалы-диверсанты «Антихов», подсыпающие проклятую соль в припасы в портах Вольска или Тирренгарда.", RewardOrConsequence = "Спасённая команда (если плывут на чужом судне) дарит долю груза или амулет от морской болезни.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-12", Category = "water", Min = 45, Max = 48, Title = "МИРОВОЙ БОСС: Око над волнами (Бехолдер из Тьмы)", Mood = "boss", Regions = "Море Скорби · Воды близ Закатного Берега", Tags = new string[] { "darklands" }, AfterMinesOnly = false, Summary = "Вода вскипает, и из низкого грозового облака над кораблём спускается парящий многоглазый ужас.", SceneDetails = "Аберрация спустилась с пролетавшего мимо разлома или чёрного галеона, чтобы потопить одиночное судно дезинтегрирующими лучами.", ChoicesOrChecks = "Нырять под палубу, срубать горящие снасти, ставить дымовую завесу и гнать судно в скалы/туман.", MasterSecret = "", RewardOrConsequence = "См. подробный блок «Многоглазый Ужас Тёмных Земель».", LinkedCombatId = "cmb-boss-beholder" },
                new EncounterItem { Id = "water-13", Category = "water", Min = 49, Max = 52, Title = "Тело пропавшего матроса в шлюпке", Mood = "mystery", Regions = "Воды у Порта Крови · Залив Фисля · Река Тирий", Tags = new string[] { "vampires" }, AfterMinesOnly = false, Summary = "Пустая яличка бьётся о борт; внутри — мёртвый боцман с двумя аккуратными проколами на шее.", SceneDetails = "Его рука сжимает медальон «Светлейшей Республики Фисль» и клочок чёрного бархата, явно сорванного с нападавшего.", ChoicesOrChecks = "Медицина/Расследование Сл 12 — убит не на суше, а прямо на воде этой ночью; на груди царапина в форме полумесяца — знак личной мести Аманжа против шпиона Ковена Десяти Клинков.", MasterSecret = "Убитый матрос был связным вампиров Ноктариса в Фисле. Аманж методично зачищает сеть своих бывших хозяев.", RewardOrConsequence = "Тяжёлый морской тесак, ключ от портовой ячейки в Фисле и 15 серебряных монет.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-14", Category = "water", Min = 53, Max = 56, Title = "Белый морской туман и фантомные колокола", Mood = "hazard", Regions = "Залив Фисля · Река Тирий · Побережье Закатного Берега", Tags = new string[] { "wild", "darklands" }, AfterMinesOnly = false, Summary = "Густой холодный туман съедает ориентиры, а со всех сторон звенят призрачные рынды несуществующих кораблей.", SceneDetails = "Компас вращается кругами, рифы рядом. Если идти на звон колоколов — судно попадёт на мель или в лапы упырей.", ChoicesOrChecks = "Выживание (или Водный транспорт Сл 13) — вести корабль по глубине лота и течению, игнорируя звуковые иллюзии. При провале — пробоина в днище (нужен ремонт или срочная откачка воды).", MasterSecret = "Эффект усиливается вблизи затопленных руин и морских проклятий Тёмных Земель.", RewardOrConsequence = "Выйдя из тумана, команда замечает на отмели брошенный спасательный буй с привязанным гермомешком (паёк и 20 зм).", LinkedCombatId = "" },
                new EncounterItem { Id = "water-15", Category = "water", Min = 57, Max = 60, Title = "Боевой энкаунтер: Бесшумные твари из трюма", Mood = "combat", Regions = "Море или речная баржа", Tags = new string[] { "illithids" }, AfterMinesOnly = true, Summary = "Ночью на палубе слышен влажный шлёпающий звук — из воды или трюмного ящика выбрались охотники за мозгом.", SceneDetails = "Матросы в панике, вахтенный сидит с остекленевшим взглядом, а из темноты трюма светятся бледные силуэты.", ChoicesOrChecks = "Тесный бой в ограниченном пространстве палубы и кают.", MasterSecret = "", RewardOrConsequence = "См. боевой блок «Твари Психического Поиска».", LinkedCombatId = "cmb-illithid-beasts" },
                new EncounterItem { Id = "water-16", Category = "water", Min = 61, Max = 64, Title = "Шквальный шторм и сломанный руль", Mood = "hazard", Regions = "Открытое море · Устье широкой реки", Tags = new string[] { "wild" }, AfterMinesOnly = false, Summary = "Чёрные валы заливают палубу, ветер рвёт парус, а тяжеленный румпель вырывается из рук рулевого.", SceneDetails = "Это не просто одна проверка Акробатики — начинается динамическая сцена выживания в 3 такта: удержать мачту, закрепить катящийся по палубе груз и выправить руль, пока судно не швырнуло на скалы.", ChoicesOrChecks = "Групповой вызов (нужны 3 успеха из 4): Сила/Атлетика (удержать румпель Сл 13), Ловкость/Акробатика (поймать груз или залезть на рею Сл 13), Водный транспорт/Природа (прочитать волну Сл 12), Магия/Ремесло (укрепить снасти).", MasterSecret = "Хранители Вольска считают такие бури отголоском ярости Истишии и Акади из-за диверсий Антихов.", RewardOrConsequence = "Успех — судно цело, команда в восторге (+репутация и бесплатный проезд); провал — потеря 1 ящика припасов и 1 уровень истощения у всей команды.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-17", Category = "water", Min = 65, Max = 68, Title = "Стая голодных акул и суеверные матросы", Mood = "social", Regions = "Открытое море", Tags = new string[] { "wild" }, AfterMinesOnly = false, Summary = "Десяток огромных серых плавников режет воду за кормой — матросы в панике выбрасывают за борт свежие припасы.", SceneDetails = "Боцман кричит, что это «акулы-вестницы» и если не откупиться мясом (или не прогнать их), они перевернут шлюпку у самого берега. Одна из акул необычно крупная, с обломком гарпуна и блестящим талисманом в пасти.", ChoicesOrChecks = "Убеждение/Запугивание Сл 13 — остановить порчу ценной еды экипажа. Природа Сл 12 — понять, что их приманила сочащаяся из трюма кровь или нежить на борту.", MasterSecret = "В трюме действительно может быть спрятан раненый/мёртвый пассажир или бочка с контрабандным мясом/кровью для вампира.", RewardOrConsequence = "Сохранение провизии команды или добытый из воды редкий амулет моряка (преимущество против утопления).", LinkedCombatId = "" },
                new EncounterItem { Id = "water-18", Category = "water", Min = 69, Max = 72, Title = "Боевой энкаунтер: Абордаж вампиров Аманжа", Mood = "combat", Regions = "Любая вода ночью", Tags = new string[] { "vampires" }, AfterMinesOnly = true, Summary = "Летучие мыши срываются с облаков прямо на мачты и превращаются в бледных убийц.", SceneDetails = "Вампирские отродья быстро блокируют спуск в каюты и смеются, перепрыгивая с реи на рею.", ChoicesOrChecks = "Бой с использованием факелов, серебра и воды (текущая река может быть препятствием/бонусом по усмотрению мастера!).", MasterSecret = "", RewardOrConsequence = "См. подробный блок «Ночная стая лорда Аманжа».", LinkedCombatId = "cmb-vampires" },
                new EncounterItem { Id = "water-19", Category = "water", Min = 73, Max = 76, Title = "Гигантский водоворот у затопленных врат", Mood = "hazard", Regions = "Устье Тирия · Лагуна Фисля · Море Скорби", Tags = new string[] { "wild" }, AfterMinesOnly = false, Summary = "Вода с рёвом закручивается в огромную воронку диаметром в сотню ярдов, затягивая судно на дно.", SceneDetails = "В самом центре воронки на долю секунды видны каменные столбы затонувшего портала Старого Мориона. Нужна слаженная командная работа всех участников.", ChoicesOrChecks = "Командное испытание (каждый игрок выбирает роль на 1 раунд, Сл 13): гребцы/ветер (Сила или Магия), рулевой (Водный транспорт/Восприятие), балласт/паруса (Акробатика/Ловкость).", MasterSecret = "Водоворот открывается раз в несколько дней из-за колебаний подводного элементального разлома, связанного с Вольском.", RewardOrConsequence = "Успешный выход даёт ускорение по течению на целый день пути; провал затягивает к подводным пещерам или ломает весла.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-20", Category = "water", Min = 77, Max = 80, Title = "Плавучая баржа-крепость «Взгляда Совы»", Mood = "social", Regions = "Река Тирий · Река Аргент · Путь Тирон — Вольск — Фисль", Tags = new string[] { "owls", "illithids" }, AfterMinesOnly = false, Summary = "Огромная тяжелобронированная баржа с баллистами, знаменем Золотой Совы и охраной «Ночных Крыльев» идёт на встречных курсах.", SceneDetails = "Капитан-командор гильдии в синем плаще предлагает выкупить редкие трофеи или подвезти героев до Вольска/Тирона за звонкую монету — но категорически запрещает подходить к запечатанному носовому трюму.", ChoicesOrChecks = "Скрытность/Ловкость рук Сл 15 — подслушать разговор фактора с офицером («груз живой, держите на льду до Тирона») или заглянуть в накладную. Либо честная торговля.", MasterSecret = "Именно по рекам Тирий и Аргент «Взгляд Совы» безнаказанно перебрасывает личинок, рабов и артефакты Иллитидов прямо в сердце столицы.", RewardOrConsequence = "Успешная разведка даёт улику против дома Рейкваеров; при тревоге — переход в бой «Зачистка Ночных Крыльев».", LinkedCombatId = "cmb-owls-wings" },
                new EncounterItem { Id = "water-21", Category = "water", Min = 81, Max = 84, Title = "Речной досмотр Хранителей Вольска", Mood = "social", Regions = "Река Тирий близ Вольска", Tags = new string[] { "empire", "antihi" }, AfterMinesOnly = false, Summary = "Лёгкая ладья под голубым флагом храма Истишии останавливает суда на речном тракте.", SceneDetails = "Стражи Водного района ищут контрабандный алхимический огонь и листовки «Антихов» после недавнего покушения на хранителей. Вода вокруг ладьи странно послушна жезлу жреца.", ChoicesOrChecks = "Убеждение Сл 12 — показать отсутствие взрывчатки и рассказать, что творится в низовьях или у Востоколя.", MasterSecret = "Жрец Истишии признаётся вполголоса, что течения реки Тирий в последнее время пахнут чужеродной магией снизу, не похожей ни на одну из четырёх стихий.", RewardOrConsequence = "Снабжают 1 флаконом благословлённой воды Вольска (снимает усталость или лечит 2d4) и пропуском в четыре района Вольска.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-22", Category = "water", Min = 85, Max = 88, Title = "Гондольер-контрабандист из Порта Крови", Mood = "social", Regions = "Пролив у Фисля · Граница Ноктариса", Tags = new string[] { "vampires", "owls" }, AfterMinesOnly = false, Summary = "Узкая чёрная лодка без огней бесшумно подходит к борту; гребец в серебряной полумаске предлагает тайную сделку.", SceneDetails = "Это дампир («Тень») из Ноктариса, бежавший из-под власти Ковена Десяти Клинков (или работающий на Аманжа). Он продаёт редкие яды, чёрный обсидиан или информацию о вампирских войнах.", ChoicesOrChecks = "Проницательность Сл 14 — он искренне ненавидит как «мясные фермы» Ноктариса, так и наглецов из Взгляда Совы. Торг или обмен слухами.", MasterSecret = "За хорошую плату или услугу может передать партию наводку на тайную встречу агентов Аманжа и назвать настоящие имена двух шпионов в Фисле.", RewardOrConsequence = "Можно купить редкий ноктарисский яд (1 доза, 45 зм), обсидиановый клинок или карту Порта Крови.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-23", Category = "water", Min = 89, Max = 92, Title = "Призрачная переправа на Реке Слёз", Mood = "omen", Regions = "Река Слёз (граница с Эльмаэлем у Гринока)", Tags = new string[] { "elves", "darklands" }, AfterMinesOnly = false, Summary = "Ночью над рекой поднимается холодный голубоватый пар, и на воде появляются тени древних лодок.", SceneDetails = "Слышны тихие женские рыдания и прощальные слова — память о столетиях войны людей и эльфов. Но сегодня сквозь плач пробивается чей-то живой крик помощи с противоположного берега.", ChoicesOrChecks = "Восприятие Сл 13 — на том берегу в корнях ивы запутался раненый эльфийский гонец или пропавший охотник Гринока! Спасбросок Мудрости Сл 12 от тоски Реки Слёз.", MasterSecret = "Если спасти эльфа, он назовёт пароль прохода в Лаэринор («Поющий Брод») — единственное место Эльмаэля, торгующее с людьми.", RewardOrConsequence = "Уважение клана «Пронзительная Стрела» в Гриноке или эльфийский знак доверия.", LinkedCombatId = "" },
                new EncounterItem { Id = "water-24", Category = "water", Min = 93, Max = 96, Title = "Тайная разгрузка у лесного причала (Взгляд Совы)", Mood = "combat", Regions = "Река Тирий · Река Аргент · Глухая бухта у Фисля", Tags = new string[] { "owls", "illithids" }, AfterMinesOnly = false, Summary = "Под покровом ночи трое людей в капюшонах сгружают с когга связанные тела и тяжёлые кристаллы в фургон.", SceneDetails = "Охраняют разгрузку бойцы «Ночных Крыльев». Один из пленников без кляпа хрипло кричит в темноту: «Спасите, нас везут в Тихий Лог!»", ChoicesOrChecks = "Скрытное спасение (Скрытность Сл 14) или внезапная атака на причале, чтобы освободить пленников и захватить офицера.", MasterSecret = "", RewardOrConsequence = "См. боевой блок «Зачистка Ночных Крыльев» + спасённые свидетели расскажут о связи Рейкваеров и похищений.", LinkedCombatId = "cmb-owls-wings" },
                new EncounterItem { Id = "water-25", Category = "water", Min = 97, Max = 100, Title = "МИРОВОЙ БОСС: Белуатье на чёрной каравелле", Mood = "boss", Regions = "Открытое море · Широкое устье Тирия", Tags = new string[] { "vampires" }, AfterMinesOnly = true, Summary = "Брошенная вами тень на палубе вдруг вытягивается — и рядом со штурвалом уже стоит правая рука лорда Аманжа.", SceneDetails = "Он появился на борту без всплеска, со стаканом багрового вина в руке, в окружении двух отродий на мачтах. Чёрная каравелла стоит на траверзе в ста ярдах.", ChoicesOrChecks = "Бегство в шлюпках, отчаянная сделка, сдача трофея или блестящая дипломатия ради жизни.", MasterSecret = "", RewardOrConsequence = "См. подробный блок «Белуатье — Правая рука лорда Аманжа».", LinkedCombatId = "cmb-boss-beluatye" }
            };
