        private static List<CombatItem> BuildCombats()
        {
            return new List<CombatItem>
            {
                new CombatItem { Id = "cmb-darklands", Min = 1, Max = 12, Title = "Авангард Тёмных Земель", IsBoss = false, AfterMinesOnly = false, Tags = new string[] { "darklands" }, Enemies = "5–6 Восставших трупов с чёрной коркой + 1 Ученик-некромант (или Низший демон при эскалации)", DangerLevel = "Средняя угроза", Motivation = "Отряд прорвался от портала на месте Деревушки на болоте (южнее Востоколя) или высадился с Закатного Берега. Ищут очаг магии или добивают отставших беженцев.", Tactics = "Трупы лезут напролом и связывают ближним боем (слабо реагируют на святые символы). Некромант прячется в кустах/тумане, поднимает павших и пытается наложить проклятие тьмы.", TwistOrSecret = "У некроманта на шее медальон с совой — он покупал трупы или карты маршрутов через посредников «Взгляда Совы» (или крал их по приказу из-под Востоколя).", Reward = "Обрывок карты маршрута скверны к Востоколю, 2× Лечебное зелье Альфонса, 1× Эликсир здоровья (или Противоядие Амунет), чёрный обсидиановый фокус (40 зм)." },
                new CombatItem { Id = "cmb-bandits", Min = 13, Max = 24, Title = "Мародёры разорившихся трактов", IsBoss = false, AfterMinesOnly = false, Tags = new string[] { "empire", "wild" }, Enemies = "1 Главарь (ветеран из-под Корна или пират Фисля) + 4–5 Бандитов-арбалетчиков", DangerLevel = "Низкая / Средняя", Motivation = "Война и падение Востоколя лишили людей крова и торговли. Им нужны провизия, бочонки эля, лошади и тёплое снаряжение.", Tactics = "Сначала не бьют на поражение: перекрывают дорогу поваленным деревом или баркасом, требуют выкуп («Отдайте половину еды или бочонок воды»). При первой потере лидера сдаются.", TwistOrSecret = "Один из бандитов — «Предатель Крови» (орк/гоблин со спиленными клыками, бежавший из орды Зорга) либо бывший крестьянин из сгоревшего Корна, знающий про запечатанные катакомбы Вальгула.", Reward = "2× Лечебное зелье, 1× Базовый яд (Воло) или Масло точности, фляга с подлинным «Кончаемым Элем», 25–45 зм в монетах Фисля и Тирона." },
                new CombatItem { Id = "cmb-deserters", Min = 25, Max = 36, Title = "Дезертиры разбитого гарнизона Востоколя", IsBoss = false, AfterMinesOnly = false, Tags = new string[] { "empire" }, Enemies = "4–6 Имперских пехотинцев-разведчиков (помятые латы, арбалеты, алебарды)", DangerLevel = "Средняя угроза", Motivation = "Бежали из-под павшего Востоколя или с передовой у Чёрного Шпиля. В панике, истощены, боятся имперской инквизиции за дезертирство.", Tactics = "Атакуют с нервной дистанции без долгого торга, принимая хорошо вооружённую группу за дозор Сената или «охотников за головами». Бегут, если падает половина отряда или если показать имперский медальон/грамоту.", TwistOrSecret = "Их командир шепчет о том, что «ворота Востоколя открылись изнутри — кто-то в синем плаще с золотой совой перебил стражу у башни ещё до подхода демонов».", Reward = "Имперская форма (маскировка), 1× Улучшенное лечебное зелье (4d4+4) + 1× Слабое зелье героизма (Воло), медальон гарнизона Востоколя и 20 арбалетных болтов." },
                new CombatItem { Id = "cmb-illithid-beasts", Min = 37, Max = 48, Title = "Твари Психического Поиска", IsBoss = false, AfterMinesOnly = true, Tags = new string[] { "illithids" }, Enemies = "2 Пожирателя разума (Intellect Devourers) или 1 Слепой ужас + 2 Гримлока", DangerLevel = "Высокая угроза (смертельно при провале ИНТ)", Motivation = "Вышли по следу псионического резонанса: чувствуют осколок Камня, заражённую кровь или носителей метки после шахт Тихого Лога.", Tactics = "Действуют абсолютно бесшумно из темноты, избегая света факелов. Стараются сбить с ног мага или следопыта и перехватить контроль над телом, пока гримлоки отвлекают бойцов.", TwistOrSecret = "Внутри их логов и желудков находят свежие бирки складского учёта «Взгляда Совы» — тварей доставляли в запечатанных свинцовых контейнерах под видом «алхимических компонентов из Фисля».", Reward = "1× Малое зелье ангельской передышки (Воло, восст. ячейки 1–2 ур.), 1× Зелье ночного зрения, пульсирующий фиолетовый кристалл-имплант (120 зм), записка с шифром Рейкваеров." },
                new CombatItem { Id = "cmb-vampires", Min = 49, Max = 60, Title = "Ночная стая лорда Аманжа", IsBoss = false, AfterMinesOnly = true, Tags = new string[] { "vampires" }, Enemies = "3–4 Вампирских отродья Аманжа (в чёрных плащах без герба Ковена Десяти Клинков)", DangerLevel = "Высокая угроза (особенно ночью)", Motivation = "Отколовшиеся от Ноктариса слуги Аманжа выслеживают сильных путников и артефакты. Их цель — ослабить как Империю, так и Ковен Десяти Клинков.", Tactics = "Ждут захода солнца или густого тумана. Атакуют с крыш/деревьев/борта шлюпки, стараются утащить одного ослабленного героя в темноту. Отступают при виде яркого солнечного света или серебряного оружия.", TwistOrSecret = "Отродья презирают «мясников из Ноктариса» и прямо заявляют, что лорд Аманж ищет союзников против «длинногловых паразитов, купивших Тиронский тракт».", Reward = "Посеребрённый кинжал с руной Аманжа, 1× Зелье скорости (Компендиум) + 1× Улучшенное лечебное зелье, запечатанная записка с печатью Аманжа." },
                new CombatItem { Id = "cmb-owls-wings", Min = 61, Max = 69, Title = "Зачистка «Ночных Крыльев» (Взгляд Совы)", IsBoss = false, AfterMinesOnly = false, Tags = new string[] { "owls", "illithids" }, Enemies = "1 Офицер «Ночных Крыльев» (свитки Тьмы и Ускорения) + 4 Бойца в тёмно-синих сюрко и кабассетах", DangerLevel = "Высокая тактическая угроза", Motivation = "Герои увидели лишнее: разгрузку фиолетовых кристаллов, похищение «свидетелей» или тайную переправу по реке Тирий.", Tactics = "Работают профессионально, как ЧВК: бросают свиток Туманного облака или Тьмы, бьют залпами тяжёлых арбалетов, в тесноте переходят на абордажные сабли. Стараются не оставлять свидетелей.", TwistOrSecret = "Рядовые «Крылья» уверены, что охраняют контрабандный порошок и артефакты Фисля от грабителей. Лишь у офицера под маской — лёгкая мутность глаз и приказ: «Живых доставить фактору Рейкваеров».", Reward = "1× Зелье невидимости (Компендиум) + 1× Яд дроу (Воло), тяжёлые арбалеты, свиток Ускорения/Тьмы, маршрутная ведомость гильдии и 75 золотых «фислей»." },
                new CombatItem { Id = "cmb-antihi-cell", Min = 70, Max = 76, Title = "Фанатики-поджигатели «Антихов»", IsBoss = false, AfterMinesOnly = false, Tags = new string[] { "antihi" }, Enemies = "1 Проповедник-алхимик + 4 Боевика с зажигательными смесями и кинжалами", DangerLevel = "Средняя угроза", Motivation = "Считают, что бури, наводнения и падение Востоколя — кара за поклонение стихийным богам (Коссуту, Истишии, Грумбару, Акади). Атакуют святилища, речные баржи Вольска и магов.", Tactics = "Днём выглядят как обычные горожане и спорщики, ночью кидают алхимический огонь и пытаются прорваться к заклинателям («Потушим ваш хаос!»). Иногда случайно выпускают неуправляемого малого элементаля.", TwistOrSecret = "Кто-то снабжает ячейки «Антихов» деньгами и листовками от имени Антиха Иоганна, чтобы в хаосе поджогов Вольска отвлечь Хранителей от тайных раскопок под рекой Тирий.", Reward = "1× Зелье сопротивления огню (Компендиум) + 1× Зелье огненного дыхания (Альфонс), 2 склянки алхимического огня, пачка подпольных газет Вольска." },
                new CombatItem { Id = "cmb-elven-raiders", Min = 77, Max = 82, Title = "Ночной дозор Теневой Твердыни", IsBoss = false, AfterMinesOnly = false, Tags = new string[] { "elves" }, Enemies = "3–4 Эльфийских следопыта из Эльмаэля + 1 Мастер иллюзий из Лаэринора", DangerLevel = "Высокая угроза (засада)", Motivation = "Выслеживают нарушителей границы за Рекой Слёз, ищут пропавших охотников Гринока или агентов Круга Небесных Тел (которого ненавидят за предательство Гиацинтии).", Tactics = "Атакуют с крон деревьев или из-за миражей. Иллюзионист создаёт ложные отряды и туман, следопыты бьют прицельно по магам и свету. Готовы к переговорам, если показать знак Гринока или доказать борьбу против Тьмы.", TwistOrSecret = "Эльфы сами встревожены: в древних дубах на границе появилась фиолетовая плесень, не похожая на обычную некромантию Тёмных Земель.", Reward = "1× Масло скольжения (Амунет) + 1× Малое зелье тайных знаний (Воло), эльфийский плащ-маскировка, 20 посеребрённых стрел и шанс получить пропуск в Лаэринор." },
                new CombatItem { Id = "cmb-boss-zorg", Min = 83, Max = 88, Title = "МИРОВОЙ БОСС: Авангард Зорга «Кровожадной Пасти»", IsBoss = true, AfterMinesOnly = false, Tags = new string[] { "orcs" }, Enemies = "Военачальник Кровавых Кочевников (или сам Зорг на разведке) + 2 Огра-тарана + 4 Хобгоблина-арбалетчика", DangerLevel = "СМЕРТЕЛЬНО — НЕ ВСТУПАТЬ В ЛОБОВОЙ БОЙ", Motivation = "Разведка боем от «Гнезда» (Горы Ивакура) в сторону Нодгарда и Врат Крон-Дара. Проверяют время реакции гарнизонов Северной Марки.", Tactics = "Хобгоблины бьют строем длинными копьями и арбалетами, огры проламывают любые баррикады, орки криком ломают боевой дух. Прямой бой для партии низкого/среднего уровня — верная гибель: нужно прятаться, обваливать тропу или уводить орду.", TwistOrSecret = "Зорг «слышит ветер» и понимает, что на юге творится что-то неестественное. Если бросить ему в ноги доказательство угрозы Иллитидов или спасти раненого разведчика ради вызова чести, он может дать 30 секунд уйти, «чтобы добыча стала жирнее».", Reward = "За победу или успешный срыв разведки любым способом — УНИКАЛЬНЫЙ ХОУМБРЮ-ПРЕДМЕТ «Клык Кровожадной Пасти» (Редкий, 4 200 зм: +1 атака/урон, иммунитет к Испугу, рёв на 2к6+ТЕЛ временных ХП союзникам 1/кор. отдых) + 1× Зелье силы (Сила 21) + 1× Слабое зелье кровожадности (Воло) + карта постов Северной Марки." },
                new CombatItem { Id = "cmb-boss-beholder", Min = 89, Max = 94, Title = "МИРОВОЙ БОСС: Многоглазый Ужас Тёмных Земель", IsBoss = true, AfterMinesOnly = false, Tags = new string[] { "darklands" }, Enemies = "1 Боевой Бехолдер Тьмы + 2 Гримлока-раба (или 3 Восставших трупа)", DangerLevel = "СМЕРТЕЛЬНО — БЕЖАТЬ И ИСКАТЬ УКРЫТИЯ", Motivation = "Живое осадное орудие высшей боевой касты Тёмных Земель. Прорвался с западного фронта или через разлом у Востоколя, зачищает побережье/тракт.", Tactics = "Парит над полем боя, центральное око гасит магию, боковые лучи дезинтегрируют, парализуют и превращают в камень. Прямой бой без укрытий и ослепления — гибель. Спасение — дым, трюмы, пещеры, зеркала, тактическое бегство.", TwistOrSecret = "В отличие от обычных бехолдеров, эта тварь лишена хаотичной болтливости — она движется по чёткой военной команде, словно чей-то дрон, и избегает повозок с эмблемой Золотой Совы.", Reward = "За уничтожение или изгнание босса — УНИКАЛЬНЫЙ ХОУМБРЮ-ПРЕДМЕТ «Хрустальное око Пустоты» (Очень редкий, 18 500 зм: +2 к СЛ заклинаний, 4 заряда на микро-конус антимагии 15 фт. или Противодействие заклинанию 4 круга, вибрирует рядом с Иллитидами) + 1× Зелье полёта + 1× Улучшенное лечебное зелье + 250 зм за образцы тканей." },
                new CombatItem { Id = "cmb-boss-beluatye", Min = 95, Max = 100, Title = "МИРОВОЙ БОСС: Белуатье — Правая рука лорда Аманжа", IsBoss = true, AfterMinesOnly = true, Tags = new string[] { "vampires" }, Enemies = "Белуатье (высший вампир-дуэлянт, Младшая/Высшая Кровь) + 2 элитных Отродья", DangerLevel = "СМЕРТЕЛЬНО — БЕЖАТЬ, ДОГОВАРИВАТЬСЯ ИЛИ СДАТЬСЯ", Motivation = "Появляется только после пролога. Проверяет, кто смеет копаться в шахтах, собирать осколки и вмешиваться в тайную войну между Аманжем, Ноктарисом и «Взглядом Совы».", Tactics = "Он не хочет убивать партию сразу — он играет с ней. Обезоруживает, ловит клинок голыми руками, шутит с благородной жестокостью, запоминает лица каждого героя. При реальной угрозе растворяется в стае летучих мышей или тумане.", TwistOrSecret = "Белуатье бросает фразу: «Передайте Рейкваерам, что море и тракты не принадлежат кальмарам. А вы — живите. Лорд Аманж любит тех, кто умеет выживать… пока ему это выгодно».", Reward = "За победу, достойную дуэль или успешную сделку — УНИКАЛЬНЫЙ ХОУМБРЮ-ПРЕДМЕТ «Перстень Багровой Клятвы» (Очень редкий, 24 000 зм: сопр. некротике, Тёмное зрение +60 фт., 3/день +2к8 некро с вампирским отхилом половины) + 1× Эликсир здоровья (Медика Плантарум) + 1× Зелье героизма (Альфонс) + наводка на шпионов Взгляда Совы." }
            };
        }

        private static List<CombatTierItem> BuildCombatScalings()
